export const CONTRACT_TEMPLATE_VERSION = "1.0";

export const CONTRACT_TEMPLATE_EN = "# Machine-Fillable Template — English (HTML)\n\nThis is the complete, server-renderable English contract template. It contains the master agreement, the order schedule, and the data protection addendum in one A4 print-ready file. The clean downloadable file is attached as the artifact `template-en.html`.\n\n**Rules for engineering:** replace every double-brace variable; do not edit legal clauses. The variable register is in the `version-log` document, section 5. The Arabic template uses the same variable names.\n\nThe full HTML source follows in a code block. The source is the authoritative template.\n\n```html\n<!DOCTYPE html>\n<html lang=\"en\" dir=\"ltr\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>KiddyApp Daycare Services Agreement — Template (English)</title>\n<style>\n@page { size: A4; margin: 20mm 18mm 22mm 18mm;\n  @bottom-center { content: \"KiddyApp — Draft for review by an Egyptian-licensed attorney — {{CONTRACT_REF}}\"; font-size: 8pt; color: #8a1c1c; }\n  @top-right { content: \"Version {{TEMPLATE_VERSION}}\"; font-size: 8pt; color: #777; }\n}\n* { box-sizing: border-box; }\nhtml { font-size: 11pt; }\nbody { font-family: Georgia, \"Times New Roman\", serif; color: #111; line-height: 1.55; margin: 0; }\n.cover { page-break-after: always; padding-top: 28mm; text-align: center; }\n.cover .rule { border-top: 2px solid #111; border-bottom: 2px solid #111; padding: 10mm 4mm; margin: 0 4mm; }\n.cover h1 { font-size: 26pt; margin: 0 0 6mm; letter-spacing: .5px; }\n.cover h2 { font-size: 15pt; font-weight: normal; margin: 0; }\n.cover .meta { margin-top: 18mm; font-size: 10.5pt; text-align: left; display: inline-block; }\n.cover .meta td { padding: 1.5mm 4mm 1.5mm 0; vertical-align: top; }\n.draft { background: #fbe9e9; border: 1px solid #b3261e; color: #8a1c1c; padding: 4mm; margin: 0 4mm 10mm; font-weight: bold; font-size: 10.5pt; }\n.draft small { display:block; font-weight: normal; margin-top: 2mm; }\nh1 { font-size: 18pt; margin: 0 0 6mm; }\nh2 { font-size: 12.5pt; margin: 7mm 0 2.5mm; page-break-after: avoid; border-bottom: .5pt solid #999; padding-bottom: 1mm; }\nh3 { font-size: 11pt; margin: 5mm 0 2mm; page-break-after: avoid; }\np { margin: 0 0 2.5mm; text-align: justify; }\nul, ol { margin: 0 0 3mm 6mm; padding: 0; }\nli { margin-bottom: 1.2mm; text-align: justify; }\nblockquote { margin: 3mm 0; padding: 2.5mm 3mm; background: #f7f4ec; border-left: 3px solid #b08d57; font-size: 9.5pt; }\ntable { width: 100%; border-collapse: collapse; margin: 3mm 0 4mm; font-size: 8.6pt; page-break-inside: auto; }\nth, td { border: .5pt solid #777; padding: 1.4mm 1.8mm; vertical-align: top; text-align: left; }\nth { background: #eee; font-weight: bold; }\ntr { page-break-inside: avoid; }\n.var { background: #fff3cd; border-bottom: 1px dashed #b8860b; padding: 0 .6mm; font-family: \"Courier New\", monospace; font-size: 9pt; }\n.missing { background: #f8d7da; border-bottom: 1px solid #b3261e; padding: 0 .8mm; font-weight: bold; }\n.note { font-size: 9.5pt; color: #444; }\n.annex { page-break-before: always; }\n.signature { display: flex; gap: 12mm; margin-top: 10mm; page-break-inside: avoid; }\n.signature > div { flex: 1; border-top: .5pt solid #333; padding-top: 2mm; font-size: 9.5pt; }\n.signature .line { margin-top: 10mm; border-top: .5pt solid #333; }\n.footer-note { margin-top: 8mm; font-size: 8.5pt; color: #555; border-top: .5pt solid #999; padding-top: 2mm; }\ncode { font-family: \"Courier New\", monospace; font-size: 9pt; background: #f2f2f2; padding: 0 .6mm; }\n</style>\n</head>\n<body>\n<!--\n  MACHINE-FILLABLE TEMPLATE — KiddyApp daycare contract\n  Template version: {{TEMPLATE_VERSION}}\n  Fill every {{VARIABLE}} with data; do not edit legal clauses.\n  Required variables are listed in the task document \"version-log\".\n  Placeholder format: double braces, upper snake case.\n-->\n<div class=\"draft\">DRAFT FOR REVIEW BY AN EGYPTIAN-LICENSED ATTORNEY.\n<small>This document is a draft, not legal advice. Obtain review by an Egyptian-licensed attorney before sending or signing. The Arabic version prevails.</small></div>\n<div class=\"rule\"><h1>DAYCARE SERVICES AGREEMENT</h1><h2>Master Agreement, Order Schedule, and Data Protection Addendum</h2></div>\n<div class=\"meta\"><table>\n<tr><td>Contract reference:</td><td><span class=\"var\">{{CONTRACT_REF}}</span></td></tr>\n<tr><td>Provider:</td><td><span class=\"var\">{{PROVIDER_LEGAL_NAME}}</span></td></tr>\n<tr><td>Daycare:</td><td><span class=\"var\">{{DAYCARE_LEGAL_NAME}}</span></td></tr>\n<tr><td>Plan:</td><td><span class=\"var\">{{PLAN}}</span></td></tr>\n<tr><td>Effective date:</td><td><span class=\"var\">{{EFFECTIVE_DATE}}</span></td></tr>\n<tr><td>Template version:</td><td><span class=\"var\">{{TEMPLATE_VERSION}}</span></td></tr>\n</table></div>\n<p>This Daycare Services Agreement (the <strong>\"Agreement\"</strong>) is made on the Effective Date stated in the Order Schedule, by and between:</p>\n<ol>\n<li><strong>KiddyApp</strong>, a company organised under the laws of the Arab Republic of Egypt, with its registered office at <code>[PROVIDER REGISTERED ADDRESS — TO BE CONFIRMED]</code>, commercial registration number <code>[TO BE CONFIRMED]</code>, tax registration number <code>[TO BE CONFIRMED]</code>, represented by <code>[PROVIDER AUTHORISED SIGNATORY — TO BE CONFIRMED]</code> (the <strong>\"Provider\"</strong> or <strong>\"KiddyApp\"</strong>); and</li>\n</ol>\n<ol>\n<li>The daycare identified in the Order Schedule, with its legal name, registered address, commercial registration number, tax registration number, and authorised signatory stated there (the <strong>\"Daycare\"</strong>).</li>\n</ol>\n<p>The Provider and the Daycare are referred to individually as a <strong>\"Party\"</strong> and together as the <strong>\"Parties\"</strong>.</p>\n<h2>RECITALS</h2>\n<p>A. The Provider operates a software platform for the management of daycare centres, including child records, attendance, daily reports, communication, billing records, and related features (the <strong>\"Platform\"</strong>).</p>\n<p>B. The Daycare operates a childcare business in the Arab Republic of Egypt and wishes to use the Platform in its operations.</p>\n<p>C. The Parties wish to record the terms on which the Provider will provide the Platform and related services to the Daycare.</p>\n<h2>1. DEFINITIONS</h2>\n<p>1.1 In this Agreement, unless the context requires otherwise:</p>\n<ul>\n<li><strong>\"Account\"</strong> means the administrative account created for the Daycare on the Platform.</li>\n<li><strong>\"Affiliate\"</strong> means any entity that controls, is controlled by, or is under common control with a Party, where \"control\" means the ownership of more than fifty per cent (50%) of the voting rights or the power to direct management.</li>\n<li><strong>\"Applicable Law\"</strong> means all laws, regulations, decrees, and binding decisions applicable in the Arab Republic of Egypt, including the Egyptian Civil Code (Law No. 131 of 1948), the Commercial Law (Law No. 17 of 1999), the Personal Data Protection Law (Law No. 151 of 2020) and its Executive Regulations, the Anti-Cyber and Information Technology Crimes Law (Law No. 175 of 2018), and the Electronic Signature Law (Law No. 15 of 2004).</li>\n<li><strong>\"Authorised User\"</strong> means an individual whom the Daycare permits to access the Account, including owners, administrators, teachers, caregivers, and staff.</li>\n<li><strong>\"Child Data\"</strong> means personal data relating to a child enrolled or formerly enrolled at the Daycare, including identification, health, attendance, developmental, and learning records.</li>\n<li><strong>\"Family Data\"</strong> means personal data relating to a parent, guardian, family member, or authorised pickup person.</li>\n<li><strong>\"Confidential Information\"</strong> has the meaning given in clause 12.</li>\n<li><strong>\"Data Protection Addendum\"</strong> or <strong>\"DPA\"</strong> means the data protection addendum attached as Annex 2.</li>\n<li><strong>\"Effective Date\"</strong> means the date stated in the Order Schedule.</li>\n<li><strong>\"Fees\"</strong> means the amounts payable by the Daycare under the Order Schedule.</li>\n<li><strong>\"Order Schedule\"</strong> means the order schedule attached as Annex 1, as completed and signed by the Parties.</li>\n<li><strong>\"Personal Data\"</strong> means any data relating to an identified or identifiable natural person, as defined in Applicable Law.</li>\n<li><strong>\"Platform Content\"</strong> means the software, user interface, text, graphics, documentation, and other materials provided by the Provider as part of the Platform, excluding Daycare Content.</li>\n<li><strong>\"Daycare Content\"</strong> means all data, records, images, documents, and other materials that the Daycare or its Authorised Users upload to or create on the Platform, including Child Data and Family Data.</li>\n<li><strong>\"Services\"</strong> means the Platform and the support services described in clause 3.</li>\n<li><strong>\"Subscription Term\"</strong> means the period stated in the Order Schedule, together with any renewal period.</li>\n<li><strong>\"User\"</strong> means an Authorised User or a parent, guardian, family member, or pickup person who accesses the Platform through the Daycare.</li>\n</ul>\n<p>1.2 Headings are for convenience only and do not affect interpretation. References to a clause or annex are references to a clause or annex of this Agreement. The singular includes the plural and the reverse. \"Including\" means \"including without limitation\".</p>\n<h2>2. ORDER OF PRECEDENCE</h2>\n<p>2.1 If there is a conflict between documents, the following order of precedence applies:</p>\n<p>(a) the Data Protection Addendum, for matters relating to Personal Data;</p>\n<p>(b) the Order Schedule, for commercial variables;</p>\n<p>(c) the body of this Agreement;</p>\n<p>(d) any other annex or document incorporated by reference.</p>\n<p>2.2 The Arabic version of this Agreement prevails over the English version in the event of any inconsistency, unless the Provider and the Daycare agree otherwise in writing signed by both Parties.</p>\n<h2>3. SERVICES</h2>\n<p>3.1 The Provider grants the Daycare a non-exclusive, non-transferable, revocable right to access and use the Platform during the Subscription Term, for the Daycare's internal childcare management purposes and in accordance with this Agreement.</p>\n<p>3.2 The Services include:</p>\n<p>(a) access to the Platform through the web portal and any mobile application made available by the Provider;</p>\n<p>(b) the features corresponding to the plan stated in the Order Schedule;</p>\n<p>(c) account setup, configuration support, and reasonable technical support during the Provider's normal business hours;</p>\n<p>(d) data hosting, backup, and security measures described in clause 11 and the DPA; and</p>\n<p>(e) any additional services stated in the Order Schedule.</p>\n<p>3.3 The Provider may modify, update, or replace features of the Platform from time to time, provided that the Provider does not materially reduce the core functionality of the subscribed plan during the Subscription Term.</p>\n<p>3.4 The Provider may suspend access to the Platform for scheduled maintenance, emergency maintenance, or security reasons. The Provider will give reasonable advance notice of scheduled maintenance where practicable.</p>\n<p>3.5 The Services do not include:</p>\n<p>(a) devices, internet access, or other equipment used by the Daycare or its Users;</p>\n<p>(b) payroll, accounting, tax, or legal services;</p>\n<p>(c) verification of the identity, licensing, or regulatory compliance of the Daycare; or</p>\n<p>(d) any service that Applicable Law requires to be performed by a licensed professional.</p>\n<h2>4. ACCOUNT SETUP AND ACCESS</h2>\n<p>4.1 The Provider will create the Account after the Daycare supplies the information required in the Order Schedule and completes the Provider's onboarding process.</p>\n<p>4.2 The Daycare must provide accurate, current, and complete information and must update it promptly when it changes.</p>\n<p>4.3 The Daycare is responsible for:</p>\n<p>(a) all activity under its Account and the accounts of its Authorised Users;</p>\n<p>(b) maintaining the confidentiality of login credentials;</p>\n<p>(c) ensuring that each Authorised User has the appropriate role and access level;</p>\n<p>(d) promptly disabling access for any Authorised User who leaves the Daycare or no longer requires access; and</p>\n<p>(e) notifying the Provider without undue delay of any suspected unauthorised access or security incident.</p>\n<p>4.4 The Daycare must not share Account credentials between individuals or permit access by anyone other than its Authorised Users.</p>\n<p>4.5 The Provider may access the Account to provide support, to prevent or investigate a security incident, or to comply with Applicable Law. Where practicable, the Provider will notify the Daycare before such access.</p>\n<h2>5. DAYCARE OBLIGATIONS</h2>\n<p>5.1 The Daycare must:</p>\n<p>(a) use the Platform only for lawful childcare management purposes;</p>\n<p>(b) obtain and maintain all licences, permits, and registrations required to operate its daycare;</p>\n<p>(c) obtain all consents and provide all notices required for the collection and processing of Child Data and Family Data through the Platform;</p>\n<p>(d) ensure that the Child Data and Family Data it submits are accurate and lawfully collected;</p>\n<p>(e) comply with Applicable Law, including child protection, health, safety, labour, and data protection requirements;</p>\n<p>(f) appoint a responsible contact person for the Account and for data protection matters; and</p>\n<p>(g) cooperate reasonably with the Provider in relation to security, audits, and regulatory inquiries.</p>\n<p>5.2 The Daycare is solely responsible for the care, supervision, health, safety, and education of the children at its centre. The Platform is a management tool and does not replace professional childcare judgment or the Daycare's legal obligations.</p>\n<p>5.3 The Daycare must not use the Platform to record or distribute material that is unlawful, defamatory, discriminatory, or harmful to a child.</p>\n<h2>6. ACCEPTABLE USE</h2>\n<p>6.1 The Daycare must not, and must ensure that its Users do not:</p>\n<p>(a) copy, modify, translate, reverse engineer, decompile, or attempt to derive the source code of the Platform, except as permitted by Applicable Law;</p>\n<p>(b) resell, sublicense, rent, or provide the Platform to a third party as a service;</p>\n<p>(c) interfere with the security, integrity, or performance of the Platform;</p>\n<p>(d) upload or transmit viruses, malware, or other harmful code;</p>\n<p>(e) use the Platform to send unsolicited commercial messages or to harvest data;</p>\n<p>(f) access data of another daycare or another User without authorisation;</p>\n<p>(g) use the Platform in a way that violates the privacy or rights of a child or family; or</p>\n<p>(h) use the Platform for any purpose that is unlawful under Applicable Law.</p>\n<p>6.2 The Provider may investigate suspected breaches of this clause 6 and may suspend or terminate access where a breach presents a security, legal, or child-safety risk.</p>\n<h2>7. FEES, INVOICING, AND PAYMENT</h2>\n<p>7.1 The Daycare will pay the Fees stated in the Order Schedule in Egyptian Pounds (EGP), free of any set-off or deduction, except as required by Applicable Law.</p>\n<p>7.2 The billing model depends on the plan selected in the Order Schedule:</p>\n<p>(a) <strong>Demo plan.</strong> No Fees are payable for the demo period stated in the Order Schedule. The Provider may end the demo period or convert it to a paid plan only as stated in the Order Schedule or by written agreement.</p>\n<p>(b) <strong>Monthly plan.</strong> The monthly amount is the monthly rate stated in the Order Schedule, plus the per-child rate for each active child above the free-child threshold stated in the Order Schedule.</p>\n<p>(c) <strong>Annual plan.</strong> The annual amount stated in the Order Schedule is payable once for each twelve-month billing block.</p>\n<p>7.3 The Daycare's billing cycle starts on the date stated in the Order Schedule. Unless the Order Schedule states otherwise, an invoice is issued at the end of each billing cycle and is due by the fifth (5th) day of the month following the invoice date.</p>\n<p>7.4 The Fees are exclusive of value-added tax and any other applicable taxes, unless the Order Schedule states that they are inclusive. The Daycare is responsible for any taxes, duties, or withholdings required by Applicable Law, except taxes on the Provider's income.</p>\n<p>7.5 The Provider may change the Fees for a renewal period by giving the Daycare at least sixty (60) days' written notice before the end of the current Subscription Term. If the Daycare does not accept the change, it may terminate this Agreement effective at the end of the current Subscription Term by written notice given before the renewal date.</p>\n<p>7.6 The Provider will issue invoices in electronic form and may use email or the Platform to deliver them. The Daycare must provide a valid billing contact and billing email address.</p>\n<p>7.7 All payments must be made in the manner stated in the Order Schedule or notified by the Provider in writing, including bank transfer or any payment link that the Provider makes available.</p>\n<h2>8. LATE PAYMENT AND SUSPENSION</h2>\n<p>8.1 If the Daycare does not pay an undisputed invoice by its due date, the Provider may charge late-payment interest at the rate permitted by Applicable Law from the due date until payment.</p>\n<p>8.2 If an undisputed invoice remains unpaid for more than ten (10) business days after its due date, the Provider may suspend access to the Platform after giving the Daycare at least five (5) business days' written notice.</p>\n<p>8.3 During a suspension, the Provider will preserve the Daycare's data for the period stated in the DPA. A suspension does not relieve the Daycare of its obligation to pay accrued Fees.</p>\n<p>8.4 The Provider will restore access promptly after the Daycare pays all outstanding amounts and any applicable late-payment charge.</p>\n<p>8.5 If an invoice is disputed in good faith, the Daycare must notify the Provider in writing within ten (10) business days of the invoice date, giving details of the dispute. The undisputed portion remains payable.</p>\n<h2>9. TERM AND RENEWAL</h2>\n<p>9.1 This Agreement starts on the Effective Date and continues for the Subscription Term stated in the Order Schedule.</p>\n<p>9.2 Unless the Order Schedule states otherwise:</p>\n<p>(a) a monthly plan renews automatically for successive one-month periods;</p>\n<p>(b) an annual plan renews automatically for successive twelve-month periods; and</p>\n<p>(c) a demo plan does not renew and ends at the end of the demo period unless the Parties agree in writing to a paid plan.</p>\n<p>9.3 Either Party may prevent renewal by giving written notice at least thirty (30) days before the end of the current Subscription Term, unless the Order Schedule states a different notice period.</p>\n<p>9.4 The Provider may decline to renew this Agreement by giving written notice at least sixty (60) days before the end of the current Subscription Term.</p>\n<h2>10. TERMINATION</h2>\n<p>10.1 Either Party may terminate this Agreement immediately by written notice if:</p>\n<p>(a) the other Party commits a material breach of this Agreement and does not cure the breach within thirty (30) days after receiving written notice describing the breach; or</p>\n<p>(b) the other Party becomes insolvent, enters liquidation, is subject to a bankruptcy or similar proceeding, or ceases to carry on business.</p>\n<p>10.2 The Provider may terminate this Agreement immediately by written notice if the Daycare:</p>\n<p>(a) uses the Platform in a way that creates a serious risk to a child, to the Platform, or to another person;</p>\n<p>(b) repeatedly breaches clause 6 after written warning; or</p>\n<p>(c) fails to maintain a licence or registration required to operate its daycare.</p>\n<p>10.3 The Daycare may terminate this Agreement immediately by written notice if the Provider commits a material breach of the DPA or a security incident that materially affects the Daycare's data and is not remedied within a reasonable period.</p>\n<p>10.4 On termination or expiry:</p>\n<p>(a) the Daycare's right to access the Platform ends;</p>\n<p>(b) the Daycare must pay all Fees accrued up to the effective date of termination;</p>\n<p>(c) the Provider will make the Daycare's data available for export in a standard format for thirty (30) days, unless the DPA states a different period;</p>\n<p>(d) after the export period, the Provider will delete or anonymise the Daycare's data in accordance with the DPA; and</p>\n<p>(e) each Party will return or destroy the other Party's Confidential Information, except where retention is required by Applicable Law.</p>\n<p>10.5 Clauses that by their nature should survive termination survive, including clauses 11, 12, 13, 14, 15, 16, 18, and 19.</p>\n<h2>11. DATA PROTECTION</h2>\n<p>11.1 The Parties will comply with Applicable Law on the protection of Personal Data, including the Personal Data Protection Law (Law No. 151 of 2020) and its Executive Regulations.</p>\n<p>11.2 For the purposes of the DPA:</p>\n<p>(a) the Daycare is the controller of Child Data and Family Data;</p>\n<p>(b) the Provider is the processor of Child Data and Family Data; and</p>\n<p>(c) the Provider processes Child Data and Family Data only on the Daycare's documented instructions and as required by Applicable Law.</p>\n<p>11.3 The DPA forms an integral part of this Agreement and prevails over this Agreement in the event of a conflict relating to Personal Data.</p>\n<p>11.4 The Daycare is responsible for obtaining a lawful basis for the processing of Child Data and Family Data, including any consent required from a parent or guardian, and for providing any required privacy notice.</p>\n<p>11.5 The Provider will implement appropriate technical and organisational measures to protect Personal Data, as described in the DPA.</p>\n<p>11.6 The Provider will notify the Daycare without undue delay after becoming aware of a Personal Data breach that affects the Daycare's data, and will provide the information reasonably required for the Daycare to meet its own notification obligations.</p>\n<p>11.7 The Provider may use sub-processors as described in the DPA. The Provider remains responsible to the Daycare for the performance of its sub-processors' data protection obligations.</p>\n<h2>12. CONFIDENTIALITY</h2>\n<p>12.1 <strong>\"Confidential Information\"</strong> means any information disclosed by one Party to the other in connection with this Agreement that is marked confidential or that a reasonable person would understand to be confidential, including commercial terms, pricing, customer lists, technical information, security information, Child Data, Family Data, and the contents of the Platform.</p>\n<p>12.2 Each Party must:</p>\n<p>(a) use Confidential Information only for the purposes of this Agreement;</p>\n<p>(b) protect Confidential Information with at least reasonable care;</p>\n<p>(c) disclose Confidential Information only to its employees, officers, professional advisers, and contractors who need to know it and are bound by confidentiality obligations at least as protective as this clause; and</p>\n<p>(d) not disclose Confidential Information to any other person without the disclosing Party's prior written consent, except as required by Applicable Law or a competent authority.</p>\n<p>12.3 Confidential Information does not include information that:</p>\n<p>(a) is or becomes public through no breach of this Agreement;</p>\n<p>(b) was lawfully known to the receiving Party before disclosure;</p>\n<p>(c) is received lawfully from a third party without a duty of confidence; or</p>\n<p>(d) is independently developed without use of the Confidential Information.</p>\n<p>12.4 If a Party is required by law or a competent authority to disclose Confidential Information, it must, where lawful and practicable, notify the other Party before disclosing and disclose only the minimum required.</p>\n<p>12.5 Confidentiality obligations continue during the Agreement and for three (3) years after termination or expiry. Trade secrets and Personal Data remain protected for as long as they retain that status under Applicable Law.</p>\n<h2>13. INTELLECTUAL PROPERTY</h2>\n<p>13.1 The Provider and its licensors own all rights in the Platform, Platform Content, and any improvements, modifications, or derivative works of the Platform. No rights are granted except as expressly stated in this Agreement.</p>\n<p>13.2 The Daycare and its licensors own all rights in the Daycare Content. The Daycare grants the Provider a non-exclusive, royalty-free licence to host, store, copy, process, transmit, and display the Daycare Content solely to provide the Services and as required by Applicable Law.</p>\n<p>13.3 The Daycare grants the Provider a non-exclusive, royalty-free licence to use feedback, suggestions, and ideas provided by the Daycare to improve the Platform, provided that the Provider does not identify the Daycare or disclose its Confidential Information.</p>\n<p>13.4 The Provider must not use the Daycare's name, logo, or trademarks in public marketing without the Daycare's prior written consent, except that the Provider may identify the Daycare as a customer in a private list provided to a prospective customer on a confidential basis.</p>\n<p>13.5 The Daycare must not remove, obscure, or alter any proprietary notice on the Platform.</p>\n<h2>14. WARRANTIES AND DISCLAIMERS</h2>\n<p>14.1 Each Party warrants that it has the authority to enter into this Agreement and that its signatory is duly authorised.</p>\n<p>14.2 The Provider warrants that:</p>\n<p>(a) it will provide the Services with reasonable skill and care and in accordance with this Agreement;</p>\n<p>(b) the Platform will materially conform to the documentation made available by the Provider; and</p>\n<p>(c) it will use reasonable efforts to correct reproducible defects reported by the Daycare.</p>\n<p>14.3 The Daycare warrants that:</p>\n<p>(a) it holds all licences and permits required to operate its daycare;</p>\n<p>(b) it has a lawful basis for the Child Data and Family Data it submits to the Platform; and</p>\n<p>(c) its use of the Platform will comply with Applicable Law.</p>\n<p>14.4 Except as expressly stated in this Agreement, the Provider does not warrant that the Platform will be uninterrupted, error-free, or free from harmful code. The Provider does not warrant any result from the use of the Platform.</p>\n<p>14.5 The Provider is not responsible for the accuracy of data entered by the Daycare or its Users, or for any decision the Daycare makes using the Platform.</p>\n<p>14.6 Nothing in this Agreement excludes or limits any warranty or liability that cannot be excluded or limited under Applicable Law.</p>\n<h2>15. LIMITATION OF LIABILITY</h2>\n<p>15.1 Subject to clause 15.3, each Party's total aggregate liability under this Agreement, whether in contract, tort, negligence, or otherwise, is limited to the amount stated in the Order Schedule as the liability cap.</p>\n<p>15.2 Subject to clause 15.3, neither Party is liable for indirect or consequential loss, loss of profit, loss of revenue, loss of business, loss of goodwill, or loss of data, except to the extent caused by the other Party's breach of clause 11 or clause 12.</p>\n<p>15.3 Nothing in this Agreement limits or excludes liability for:</p>\n<p>(a) fraud or wilful misconduct;</p>\n<p>(b) death or personal injury caused by negligence;</p>\n<p>(c) breach of confidentiality or data protection obligations, to the extent permitted by Applicable Law;</p>\n<p>(d) infringement of the other Party's intellectual property rights; or</p>\n<p>(e) any liability that cannot be limited or excluded under Applicable Law.</p>\n<p>15.4 The Parties agree that the limitation in clause 15.1 is reasonable having regard to the Fees, the nature of the Services, and the allocation of risk between the Parties.</p>\n<h2>16. INDEMNITY</h2>\n<p>16.1 The Provider will indemnify the Daycare against any third-party claim that the Platform, as provided by the Provider and used in accordance with this Agreement, infringes a copyright, trademark, or trade secret of that third party, provided that the Daycare:</p>\n<p>(a) promptly notifies the Provider in writing;</p>\n<p>(b) gives the Provider sole control of the defence and settlement; and</p>\n<p>(c) provides reasonable cooperation at the Provider's expense.</p>\n<p>16.2 If an infringement claim is made or likely, the Provider may, at its option:</p>\n<p>(a) obtain a right for the Daycare to continue using the Platform;</p>\n<p>(b) modify the Platform so that it is non-infringing while retaining materially equivalent functionality; or</p>\n<p>(c) terminate this Agreement and refund any prepaid Fees for the unexpired portion of the Subscription Term.</p>\n<p>16.3 The Daycare will indemnify the Provider against any third-party claim arising from:</p>\n<p>(a) the Daycare Content, including a claim that the Daycare did not have the right to submit it;</p>\n<p>(b) the Daycare's processing of Child Data or Family Data in breach of Applicable Law; or</p>\n<p>(c) the Daycare's breach of clause 5 or clause 6.</p>\n<p>16.4 This clause 16 states the Provider's entire liability, and the Daycare's entire remedy, for intellectual property infringement.</p>\n<h2>17. FORCE MAJEURE</h2>\n<p>17.1 A Party is not liable for a failure or delay in performing its obligations caused by an event beyond its reasonable control, including natural disaster, fire, flood, epidemic, war, civil unrest, strike, government action, failure of public telecommunications or power, or a widespread internet outage.</p>\n<p>17.2 The affected Party must notify the other Party promptly and use reasonable efforts to mitigate the effect. If the event continues for more than thirty (30) days, either Party may terminate this Agreement by written notice.</p>\n<p>17.3 This clause does not excuse the Daycare from paying Fees for Services already provided.</p>\n<h2>18. NOTICES</h2>\n<p>18.1 Notices under this Agreement must be in writing and delivered by hand, courier, registered mail, or email to the addresses stated in the Order Schedule.</p>\n<p>18.2 A notice is deemed received:</p>\n<p>(a) on delivery, if delivered by hand or courier;</p>\n<p>(b) three (3) business days after posting, if sent by registered mail; or</p>\n<p>(c) on the next business day, if sent by email before 5:00 p.m. Cairo time and no delivery failure is received.</p>\n<p>18.3 A Party may change its notice address by written notice to the other Party.</p>\n<h2>19. GOVERNING LAW AND DISPUTE RESOLUTION</h2>\n<p>19.1 This Agreement is governed by the laws of the Arab Republic of Egypt.</p>\n<p>19.2 The Parties will first attempt to resolve any dispute through good-faith negotiations between authorised representatives for at least thirty (30) days after written notice of the dispute.</p>\n<p>19.3 If the dispute is not resolved by negotiation, the competent courts located in Cairo, Egypt, have exclusive jurisdiction, unless the Parties agree in writing to arbitration.</p>\n<p>19.4 Nothing in this clause prevents a Party from seeking urgent interim relief from a competent court.</p>\n<h2>20. ENTIRE AGREEMENT</h2>\n<p>20.1 This Agreement, together with its annexes, is the entire agreement between the Parties on its subject matter and supersedes all prior discussions, proposals, and representations.</p>\n<p>20.2 Neither Party relies on any statement, representation, or warranty not expressly set out in this Agreement, except in the case of fraud.</p>\n<h2>21. AMENDMENTS</h2>\n<p>21.1 Any amendment to this Agreement must be in writing and signed by authorised representatives of both Parties.</p>\n<p>21.2 The Provider may update the Platform's features and documentation without amending this Agreement, provided that the update does not materially reduce the subscribed functionality or increase the Fees.</p>\n<h2>22. ASSIGNMENT</h2>\n<p>22.1 Neither Party may assign or transfer this Agreement, in whole or in part, without the other Party's prior written consent, except that a Party may assign it to an Affiliate or to a successor in connection with a merger, acquisition, or sale of substantially all its assets, provided that the assignee assumes the assigning Party's obligations.</p>\n<p>22.2 Any purported assignment in breach of this clause is void.</p>\n<h2>23. LANGUAGE AND COUNTERPARTS</h2>\n<p>23.1 This Agreement is executed in two versions, Arabic and English. Both versions have the same clause numbering.</p>\n<p>23.2 The Arabic version prevails in the event of any inconsistency, unless the Provider and the Daycare agree otherwise in writing signed by both Parties. The English version is provided for convenience and for any Daycare that operates in English.</p>\n<p>23.3 If a certified translation is required for a court, authority, or registration, the Daycare may obtain one at its own cost. The certified translation does not change the prevailing version unless the Parties agree in writing.</p>\n<p>23.4 This Agreement may be executed in counterparts, including by electronic signature in accordance with the Electronic Signature Law (Law No. 15 of 2004). Each counterpart is an original, and all counterparts together form one agreement.</p>\n<h2>24. GENERAL</h2>\n<p>24.1 <strong>Severability.</strong> If a provision of this Agreement is found invalid or unenforceable, the remaining provisions continue in effect, and the Parties will replace the invalid provision with a valid provision that reflects their original intent.</p>\n<p>24.2 <strong>Waiver.</strong> A failure or delay in exercising a right is not a waiver of that right. A waiver must be in writing and applies only to the specific matter stated.</p>\n<p>24.3 <strong>No partnership.</strong> This Agreement does not create a partnership, joint venture, agency, or employment relationship between the Parties.</p>\n<p>24.4 <strong>Third-party rights.</strong> No person who is not a Party has the right to enforce this Agreement, except as expressly stated.</p>\n<p>24.5 <strong>Further assurance.</strong> Each Party will do what is reasonably necessary to give effect to this Agreement.</p>\n<p>24.6 <strong>Costs.</strong> Each Party bears its own costs of negotiating and entering into this Agreement, unless the Order Schedule states otherwise.</p>\n<section class=\"annex\" id=\"annex-1\">\n<h1>ORDER SCHEDULE — ANNEX 1</h1>\n<p class=\"note\">This Order Schedule completes the Agreement. If a field is blank or marked \"TO BE CONFIRMED\", the Agreement is not ready for signature.</p>\n<h2>A. Parties</h2>\n<table class=\"order\"><thead><tr><th>ID</th><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>A1</td><td>Contract reference</td><td><span class=\"var\">{{CONTRACT_REF}}</span></td></tr><tr><td>A2</td><td>Provider legal name</td><td><span class=\"var\">{{PROVIDER_LEGAL_NAME}}</span></td></tr><tr><td>A3</td><td>Provider commercial registration no.</td><td><span class=\"var\">{{PROVIDER_CRN}}</span></td></tr><tr><td>A4</td><td>Provider tax registration no.</td><td><span class=\"var\">{{PROVIDER_TAX_ID}}</span></td></tr><tr><td>A5</td><td>Provider registered address</td><td><span class=\"var\">{{PROVIDER_ADDRESS}}</span></td></tr><tr><td>A6</td><td>Provider notice email</td><td><span class=\"var\">{{PROVIDER_NOTICE_EMAIL}}</span></td></tr><tr><td>A7</td><td>Provider authorised signatory</td><td><span class=\"var\">{{PROVIDER_SIGNATORY}}</span></td></tr><tr><td>A8</td><td>Daycare legal name</td><td><span class=\"var\">{{DAYCARE_LEGAL_NAME}}</span></td></tr><tr><td>A9</td><td>Daycare commercial name</td><td><span class=\"var\">{{DAYCARE_TRADE_NAME}}</span></td></tr><tr><td>A10</td><td>Daycare commercial registration no.</td><td><span class=\"var\">{{DAYCARE_CRN}}</span></td></tr><tr><td>A11</td><td>Daycare tax registration no.</td><td><span class=\"var\">{{DAYCARE_TAX_ID}}</span></td></tr><tr><td>A12</td><td>Daycare registered address</td><td><span class=\"var\">{{DAYCARE_ADDRESS}}</span></td></tr><tr><td>A13</td><td>Daycare billing email</td><td><span class=\"var\">{{DAYCARE_BILLING_EMAIL}}</span></td></tr><tr><td>A14</td><td>Daycare notice email</td><td><span class=\"var\">{{DAYCARE_NOTICE_EMAIL}}</span></td></tr><tr><td>A15</td><td>Daycare authorised signatory</td><td><span class=\"var\">{{DAYCARE_SIGNATORY}}</span></td></tr><tr><td>A16</td><td>Daycare signatory title</td><td><span class=\"var\">{{DAYCARE_SIGNATORY_TITLE}}</span></td></tr><tr><td>A17</td><td>Daycare data protection contact</td><td><span class=\"var\">{{DAYCARE_DP_CONTACT}}</span></td></tr><tr><td>A18</td><td>Daycare account/subdomain</td><td><span class=\"var\">{{DAYCARE_SUBDOMAIN}}</span></td></tr></tbody></table>\n<h2>B. Commercial Terms</h2>\n<table class=\"order\"><thead><tr><th>ID</th><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>B1</td><td>Plan (demo / monthly / annual)</td><td><span class=\"var\">{{PLAN}}</span></td></tr><tr><td>B2</td><td>Monthly rate (EGP)</td><td><span class=\"var\">{{MONTHLY_RATE_EGP}}</span></td></tr><tr><td>B3</td><td>Per-child rate (EGP)</td><td><span class=\"var\">{{PER_CHILD_RATE_EGP}}</span></td></tr><tr><td>B4</td><td>Free-child threshold</td><td><span class=\"var\">{{FREE_CHILD_THRESHOLD}}</span></td></tr><tr><td>B5</td><td>Annual amount (EGP)</td><td><span class=\"var\">{{ANNUAL_AMOUNT_EGP}}</span></td></tr><tr><td>B6</td><td>Currency</td><td><span class=\"var\">{{CURRENCY}}</span></td></tr><tr><td>B7</td><td>Billing cycle start</td><td><span class=\"var\">{{TERM_START}}</span></td></tr><tr><td>B8</td><td>Effective date</td><td><span class=\"var\">{{EFFECTIVE_DATE}}</span></td></tr><tr><td>B9</td><td>Initial subscription term</td><td><span class=\"var\">{{INITIAL_TERM}}</span></td></tr><tr><td>B10</td><td>Renewal term</td><td><span class=\"var\">{{RENEWAL_TERM}}</span></td></tr><tr><td>B11</td><td>Notice period for non-renewal (days)</td><td><span class=\"var\">{{NOTICE_PERIOD_DAYS}}</span></td></tr><tr><td>B12</td><td>Demo period (if B1 = demo)</td><td><span class=\"var\">{{DEMO_PERIOD}}</span></td></tr><tr><td>B13</td><td>Demo conversion plan</td><td><span class=\"var\">{{DEMO_CONVERSION_PLAN}}</span></td></tr><tr><td>B14</td><td>Liability cap (EGP)</td><td><span class=\"var\">{{LIABILITY_CAP_EGP}}</span></td></tr><tr><td>B15</td><td>Liability cap in words</td><td><span class=\"var\">{{LIABILITY_CAP_WORDS}}</span></td></tr><tr><td>B16</td><td>VAT treatment</td><td><span class=\"var\">{{VAT_TREATMENT}}</span></td></tr><tr><td>B17</td><td>Payment method</td><td><span class=\"var\">{{PAYMENT_METHOD}}</span></td></tr><tr><td>B18</td><td>Invoice due day</td><td><span class=\"var\">{{INVOICE_DUE_DAY}}</span></td></tr><tr><td>B19</td><td>Late-payment interest</td><td><span class=\"var\">{{LATE_INTEREST}}</span></td></tr><tr><td>B20</td><td>Governing courts</td><td><span class=\"var\">{{COURTS}}</span></td></tr><tr><td>B21</td><td>Prevailing language</td><td><span class=\"var\">{{PREVAILING_LANGUAGE}}</span></td></tr><tr><td>B22</td><td>Additional services</td><td><span class=\"var\">{{ADDITIONAL_SERVICES}}</span></td></tr></tbody></table>\n<h3>C. Billing Rules</h3>\n<p><strong>Monthly plan.</strong> The monthly amount is B2 plus B3 for each active child above B4. A child is counted if the child is active at any point during the billing cycle.</p>\n<p><strong>Annual plan.</strong> The annual amount B5 is payable once for each twelve-month block.</p>\n<p><strong>Demo plan.</strong> No fees are payable during B12.</p>\n<p><strong>Currency.</strong> All amounts are in Egyptian Pounds (EGP) unless B6 states otherwise.</p>\n</section>\n<p>This Data Protection Addendum (the <strong>\"DPA\"</strong>) forms part of the Daycare Services Agreement between KiddyApp (the <strong>\"Processor\"</strong>) and the Daycare (the <strong>\"Controller\"</strong>). It applies to the Processing of Personal Data in connection with the Services.</p>\n<h2>1. DEFINITIONS</h2>\n<p>1.1 Capitalised terms not defined in this DPA have the meanings given in the Agreement. In addition:</p>\n<ul>\n<li><strong>\"Controller\"</strong> means the Daycare, which determines the purposes and means of Processing Child Data and Family Data.</li>\n<li><strong>\"Processor\"</strong> means KiddyApp, which Processes Personal Data on behalf of the Controller.</li>\n<li><strong>\"Data Subject\"</strong> means a child, parent, guardian, family member, pickup person, or staff member whose Personal Data is Processed.</li>\n<li><strong>\"Personal Data Breach\"</strong> means a breach of security leading to accidental or unlawful destruction, loss, alteration, unauthorised disclosure of, or access to, Personal Data.</li>\n<li><strong>\"Process\"</strong> means any operation on Personal Data, including collection, recording, storage, use, disclosure, transfer, deletion, or destruction.</li>\n<li><strong>\"Sub-processor\"</strong> means a third party engaged by the Processor to Process Personal Data on behalf of the Controller.</li>\n<li><strong>\"Restricted Transfer\"</strong> means a transfer of Personal Data outside the Arab Republic of Egypt to a country or recipient that does not provide an adequate level of protection under Applicable Law.</li>\n</ul>\n<h2>2. ROLES AND SCOPE</h2>\n<p>2.1 The Controller is the controller of Child Data and Family Data. The Processor is the processor of that data.</p>\n<p>2.2 The Processor Processes Personal Data only:</p>\n<p>(a) on the Controller's documented instructions, including the instructions in the Agreement and this DPA;</p>\n<p>(b) as necessary to provide the Services;</p>\n<p>(c) as required by Applicable Law; and</p>\n<p>(d) for no other purpose.</p>\n<p>2.3 The Processor must notify the Controller if, in its opinion, an instruction infringes Applicable Law. The Processor may suspend performance of the instruction until the Controller confirms or changes it.</p>\n<h2>3. DATA CATEGORIES AND DATA SUBJECTS</h2>\n<p>3.1 The Processor may Process the following categories of Personal Data:</p>\n<p>(a) <strong>Child identification and enrollment data:</strong> name, date of birth, photograph, gender, nationality, enrollment status, classroom, and registration number.</p>\n<p>(b) <strong>Child health and safety data:</strong> allergies, medical notes, medication instructions, incident records, and emergency contacts.</p>\n<p>(c) <strong>Child development and learning data:</strong> attendance, daily reports, observations, milestones, assessment notes, and portfolio items.</p>\n<p>(d) <strong>Family and guardian data:</strong> name, relationship, contact details, identification details where provided, pickup authorisations, and billing contact details.</p>\n<p>(e) <strong>Staff data:</strong> name, role, contact details, classroom assignment, and login activity.</p>\n<p>(f) <strong>Usage and security data:</strong> login records, device information, IP address, audit logs, and support correspondence.</p>\n<p>3.2 The Processor does not Process special categories of Personal Data for its own purposes. Health data is Processed only to support the Controller's childcare and safety obligations.</p>\n<p>3.3 The Controller must not submit data that is excessive or irrelevant to the Services.</p>\n<h2>4. PURPOSE AND LAWFUL BASIS</h2>\n<p>4.1 The Processor Processes Personal Data for the following purposes:</p>\n<p>(a) creating and managing the Account;</p>\n<p>(b) providing childcare management features, including attendance, daily reports, communication, billing records, and learning records;</p>\n<p>(c) providing support, maintenance, and security;</p>\n<p>(d) preventing, detecting, and investigating fraud, abuse, and security incidents; and</p>\n<p>(e) complying with Applicable Law and lawful requests of competent authorities.</p>\n<p>4.2 The Controller is responsible for identifying and documenting the lawful basis for each Processing activity, including consent where required, and for providing privacy notices to Data Subjects.</p>\n<p>4.3 The Controller must obtain any consent required from a parent or guardian for the Processing of a child's Personal Data, including health data and photographs.</p>\n<h2>5. PROCESSOR OBLIGATIONS</h2>\n<p>5.1 The Processor must:</p>\n<p>(a) Process Personal Data only as described in this DPA;</p>\n<p>(b) ensure that persons authorised to Process Personal Data are bound by confidentiality obligations;</p>\n<p>(c) implement appropriate technical and organisational measures to protect Personal Data, including access controls, encryption in transit, logging, backup, and incident response;</p>\n<p>(d) assist the Controller in responding to requests from Data Subjects, to the extent possible;</p>\n<p>(e) assist the Controller in meeting its obligations relating to security, breach notification, impact assessments, and consultation with authorities;</p>\n<p>(f) make available information reasonably necessary to demonstrate compliance with this DPA; and</p>\n<p>(g) allow audits or inspections by the Controller or its independent auditor, subject to reasonable notice, confidentiality, and scope.</p>\n<p>5.2 The Processor must not sell Personal Data or use it for advertising, profiling, or any purpose unrelated to the Services.</p>\n<p>5.3 The Processor must not disclose Personal Data to a third party except as permitted by this DPA, the Agreement, or Applicable Law.</p>\n<h2>6. CONTROLLER OBLIGATIONS</h2>\n<p>6.1 The Controller must:</p>\n<p>(a) provide accurate and lawful instructions;</p>\n<p>(b) ensure that it has the right to share Personal Data with the Processor;</p>\n<p>(c) obtain and maintain all required consents and notices;</p>\n<p>(d) implement reasonable internal access controls for its own users;</p>\n<p>(e) respond to Data Subject requests that concern the Controller's own obligations; and</p>\n<p>(f) notify the Processor promptly of any instruction that may affect the lawfulness of Processing.</p>\n<h2>7. SUB-PROCESSORS</h2>\n<p>7.1 The Controller authorises the Processor to engage the sub-processors listed in Schedule A, subject to clause 7.2.</p>\n<p>7.2 The Processor must:</p>\n<p>(a) carry out appropriate due diligence on each sub-processor;</p>\n<p>(b) impose data protection obligations on each sub-processor that are at least as protective as this DPA;</p>\n<p>(c) remain liable to the Controller for the acts and omissions of its sub-processors; and</p>\n<p>(d) notify the Controller of any intended addition or replacement of a sub-processor at least thirty (30) days in advance.</p>\n<p>7.3 The Controller may object to a new sub-processor on reasonable data protection grounds by written notice within fifteen (15) days of the notice. If the Parties cannot agree, the Controller may suspend or terminate the affected Services.</p>\n<h2>8. INTERNATIONAL TRANSFERS</h2>\n<p>8.1 The Processor must not make a Restricted Transfer without the Controller's prior written consent and without ensuring that appropriate safeguards are in place under Applicable Law.</p>\n<p>8.2 If the Processor uses infrastructure or personnel outside Egypt, it must inform the Controller and implement the safeguards required by Applicable Law, including contractual safeguards and, where required, approval from the competent authority.</p>\n<p>8.3 The Controller may refuse a Restricted Transfer that it reasonably considers to create an unacceptable data protection risk.</p>\n<h2>9. RETENTION</h2>\n<p>9.1 The Processor retains Personal Data only for as long as necessary to provide the Services and to comply with Applicable Law, or as instructed by the Controller.</p>\n<p>9.2 Unless the Controller instructs otherwise in writing and Applicable Law permits, the Processor retains:</p>\n<p>(a) active Account data during the Subscription Term;</p>\n<p>(b) exportable data for thirty (30) days after termination or expiry;</p>\n<p>(c) audit logs and security records for the period required by Applicable Law; and</p>\n<p>(d) billing records for the period required by Egyptian tax and commercial law.</p>\n<p>9.3 After the retention period, the Processor must delete or anonymise Personal Data unless Applicable Law requires continued retention. Where deletion is impossible, the Processor must isolate the data and protect it from further Processing.</p>\n<h2>10. DATA SUBJECT RIGHTS</h2>\n<p>10.1 The Processor must, to the extent technically possible, assist the Controller in responding to requests for access, correction, deletion, restriction, objection, and portability.</p>\n<p>10.2 If the Processor receives a request directly from a Data Subject, it must not respond substantively on the Controller's behalf unless the Controller authorises it in writing. The Processor must refer the request to the Controller without undue delay.</p>\n<p>10.3 The Processor may charge a reasonable fee for assistance that is manifestly unfounded or excessive, subject to Applicable Law.</p>\n<h2>11. PERSONAL DATA BREACH</h2>\n<p>11.1 The Processor must notify the Controller without undue delay, and in any event within seventy-two (72) hours, after becoming aware of a Personal Data Breach affecting the Controller's Personal Data.</p>\n<p>11.2 The notification must include, to the extent available:</p>\n<p>(a) the nature of the breach and the categories and approximate number of Data Subjects affected;</p>\n<p>(b) the likely consequences of the breach;</p>\n<p>(c) the measures taken or proposed to address the breach; and</p>\n<p>(d) the contact point for further information.</p>\n<p>11.3 The Processor must investigate the breach, mitigate its effects, and cooperate with the Controller's notifications to the competent authority and Data Subjects.</p>\n<p>11.4 The Processor must not notify a competent authority or Data Subject on the Controller's behalf unless the Controller authorises it in writing or Applicable Law requires it.</p>\n<h2>12. SECURITY MEASURES</h2>\n<p>12.1 The Processor must implement and maintain appropriate technical and organisational measures, including:</p>\n<p>(a) role-based access control and least-privilege principles;</p>\n<p>(b) authentication controls and session management;</p>\n<p>(c) encryption of data in transit and, where appropriate, at rest;</p>\n<p>(d) logging and monitoring of access to Personal Data;</p>\n<p>(e) regular backup and recovery testing;</p>\n<p>(f) secure development and vulnerability management; and</p>\n<p>(g) incident response and business continuity plans.</p>\n<p>12.2 The Controller must implement appropriate controls for its own users, devices, and credentials, and must not share accounts.</p>\n<h2>13. DELETION ON TERMINATION</h2>\n<p>13.1 On termination or expiry of the Agreement, the Processor must, at the Controller's written direction:</p>\n<p>(a) return the Controller's Personal Data in a standard, machine-readable format; and</p>\n<p>(b) delete the Controller's Personal Data from its production systems and, within a reasonable period, from its backup systems.</p>\n<p>13.2 The Processor must certify deletion in writing if the Controller requests it.</p>\n<p>13.3 The Processor may retain Personal Data where required by Applicable Law, and must inform the Controller of the legal basis and retention period.</p>\n<p>13.4 If the Controller does not give a direction within thirty (30) days after termination, the Processor may delete the data after giving written notice.</p>\n<h2>14. LIABILITY, ORDER OF PRECEDENCE, AND GOVERNING LAW</h2>\n<p>14.1 The liability provisions of the Agreement apply to this DPA.</p>\n<p>14.2 This DPA prevails over the Agreement in the event of a conflict relating to Personal Data.</p>\n<p>14.3 This DPA is governed by the laws of the Arab Republic of Egypt. The Arabic version prevails.</p>\n<p>14.4 The Parties will review this DPA at least once every twelve (12) months and update it to reflect changes in Applicable Law or the Services.</p>\n<h2>SCHEDULE A — AUTHORISED SUB-PROCESSORS</h2>\n<table>\n<thead><tr><th>ID</th><th>Sub-processor</th><th>Service</th><th>Location of processing</th><th>Safeguards</th></tr></thead><tbody>\n<tr><td>S1</td><td><code><span class=\"var\">{{SUBPROCESSOR_1_NAME}}</span></code></td><td>Hosting / database</td><td><code><span class=\"var\">{{SUBPROCESSOR_1_LOCATION}}</span></code></td><td><code><span class=\"var\">{{SUBPROCESSOR_1_SAFEGUARDS}}</span></code></td></tr>\n<tr><td>S2</td><td><code><span class=\"var\">{{SUBPROCESSOR_2_NAME}}</span></code></td><td>Email delivery</td><td><code><span class=\"var\">{{SUBPROCESSOR_2_LOCATION}}</span></code></td><td><code><span class=\"var\">{{SUBPROCESSOR_2_SAFEGUARDS}}</span></code></td></tr>\n<tr><td>S3</td><td><code><span class=\"var\">{{SUBPROCESSOR_3_NAME}}</span></code></td><td>Push notifications</td><td><code><span class=\"var\">{{SUBPROCESSOR_3_LOCATION}}</span></code></td><td><code><span class=\"var\">{{SUBPROCESSOR_3_SAFEGUARDS}}</span></code></td></tr>\n</tbody></table>\n<blockquote><p><strong>Engineering note.</strong> The production sub-processor list must be confirmed from the deployed environment before signature. Do not guess provider names or locations.</p></blockquote>\n<section class=\"annex\" id=\"signatures\"><h1>Execution</h1>\n<p>By signing below, each Party confirms that it has read and agrees to this Agreement, its Order Schedule, and its Data Protection Addendum. This Agreement takes effect on the Effective Date stated in the Order Schedule.</p>\n<div class=\"signature\"><div><strong>For and on behalf of KiddyApp</strong><br><br>Name: <span class=\"var\">{{PROVIDER_SIGNATORY}}</span><br>Title: <span class=\"var\">{{PROVIDER_SIGNATORY_TITLE}}</span><br><br><br>Signature: ______________________<br><br>Date: ______________________</div>\n<div><strong>For and on behalf of the Daycare</strong><br><br>Name: <span class=\"var\">{{DAYCARE_SIGNATORY}}</span><br>Title: <span class=\"var\">{{DAYCARE_SIGNATORY_TITLE}}</span><br><br><br>Signature: ______________________<br><br>Date: ______________________</div></div>\n<p class=\"footer-note\">Draft for review by an Egyptian-licensed attorney. Do not send or sign before that review. The Arabic version prevails.</p></section>\n<p class=\"footer-note\">Template v{{TEMPLATE_VERSION}} — machine-fillable. Replace every double-brace variable; do not edit legal text.</p>\n</body>\n</html>\n\n```\n";

export const CONTRACT_TEMPLATE_AR = "# قالب قابل للتعبئة آليًا — العربية (HTML)\n\nهذا هو قالب العقد العربي الكامل القابل للعرض من الخادم. ويحتوي على الاتفاقية الرئيسية وجدول الطلب وملحق حماية البيانات في ملف واحد جاهز للطباعة بمقاس A4. والملف النظيف القابل للتنزيل مرفق كأصل `template-ar.html`.\n\n**قواعد الهندسة:** استبدل كل متغير بين قوسين مزدوجين؛ ولا تعدل البنود القانونية. وسجل المتغيرات في مستند `version-log`، القسم 5. ويستخدم القالب العربي أسماء المتغيرات نفسها.\n\nويلي النص الكامل لـ HTML في كتلة شيفرة. والنص هو القالب المعتمد.\n\n```html\n<!DOCTYPE html>\n<html lang=\"ar\" dir=\"rtl\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>قالب اتفاقية خدمات الحضانة — KiddyApp (العربية)</title>\n<style>\n@page { size: A4; margin: 20mm 18mm 22mm 18mm;\n  @bottom-center { content: \"KiddyApp — مسودة لمراجعة محامٍ مصري مرخّص — {{CONTRACT_REF}}\"; font-size: 8pt; color: #8a1c1c; }\n  @top-left { content: \"الإصدار {{TEMPLATE_VERSION}}\"; font-size: 8pt; color: #777; }\n}\n* { box-sizing: border-box; }\nhtml { font-size: 11.5pt; }\nbody { font-family: Amiri, \"Noto Naskh Arabic\", \"Traditional Arabic\", \"Times New Roman\", serif; color: #111; line-height: 1.9; margin: 0; direction: rtl; }\n.cover { page-break-after: always; padding-top: 28mm; text-align: center; }\n.cover .rule { border-top: 2px solid #111; border-bottom: 2px solid #111; padding: 10mm 4mm; margin: 0 4mm; }\n.cover h1 { font-size: 26pt; margin: 0 0 6mm; }\n.cover h2 { font-size: 15pt; font-weight: normal; margin: 0; }\n.cover .meta { margin-top: 18mm; font-size: 10.5pt; text-align: right; display: inline-block; }\n.cover .meta td { padding: 1.5mm 0 1.5mm 4mm; vertical-align: top; }\n.draft { background: #fbe9e9; border: 1px solid #b3261e; color: #8a1c1c; padding: 4mm; margin: 0 4mm 10mm; font-weight: bold; font-size: 10.5pt; }\n.draft small { display:block; font-weight: normal; margin-top: 2mm; }\nh1 { font-size: 18pt; margin: 0 0 6mm; }\nh2 { font-size: 13pt; margin: 7mm 0 2.5mm; page-break-after: avoid; border-bottom: .5pt solid #999; padding-bottom: 1mm; }\nh3 { font-size: 11.5pt; margin: 5mm 0 2mm; page-break-after: avoid; }\np { margin: 0 0 2.5mm; text-align: justify; }\nul, ol { margin: 0 6mm 3mm 0; padding: 0; }\nli { margin-bottom: 1.2mm; text-align: justify; }\nblockquote { margin: 3mm 0; padding: 2.5mm 3mm; background: #f7f4ec; border-right: 3px solid #b08d57; font-size: 9.8pt; }\ntable { width: 100%; border-collapse: collapse; margin: 3mm 0 4mm; font-size: 8.8pt; }\nth, td { border: .5pt solid #777; padding: 1.4mm 1.8mm; vertical-align: top; text-align: right; }\nth { background: #eee; font-weight: bold; }\ntr { page-break-inside: avoid; }\n.var { background: #fff3cd; border-bottom: 1px dashed #b8860b; padding: 0 .6mm; font-family: \"Courier New\", monospace; font-size: 9.5pt; direction: ltr; display: inline-block; }\n.missing { background: #f8d7da; border-bottom: 1px solid #b3261e; padding: 0 .8mm; font-weight: bold; }\n.note { font-size: 9.8pt; color: #444; }\n.annex { page-break-before: always; }\n.signature { display: flex; gap: 12mm; margin-top: 10mm; page-break-inside: avoid; }\n.signature > div { flex: 1; border-top: .5pt solid #333; padding-top: 2mm; font-size: 9.8pt; }\n.footer-note { margin-top: 8mm; font-size: 8.8pt; color: #555; border-top: .5pt solid #999; padding-top: 2mm; }\ncode { font-family: \"Courier New\", monospace; font-size: 9.5pt; background: #f2f2f2; padding: 0 .6mm; direction: ltr; display: inline-block; }\n</style>\n</head>\n<body>\n<!--\n  MACHINE-FILLABLE TEMPLATE — KiddyApp daycare contract\n  Template version: {{TEMPLATE_VERSION}}\n  Fill every {{VARIABLE}} with data; do not edit legal clauses.\n  Required variables are listed in the task document \"version-log\".\n  Placeholder format: double braces, upper snake case.\n-->\n<div class=\"draft\">مسودة لمراجعة محامٍ مصري مرخّص.\n<small>هذه الوثيقة مسودة وليست رأيًا قانونيًا. يجب الحصول على مراجعة محامٍ مصري مرخّص قبل الإرسال أو التوقيع. النسخة العربية هي المُرجَّحة.</small></div>\n<div class=\"rule\"><h1>اتفاقية خدمات الحضانة</h1><h2>الاتفاقية الرئيسية وجدول الطلب وملحق حماية البيانات</h2></div>\n<div class=\"meta\"><table>\n<tr><td>مرجع العقد:</td><td><span class=\"var\">{{CONTRACT_REF}}</span></td></tr>\n<tr><td>المزوّد:</td><td><span class=\"var\">{{PROVIDER_LEGAL_NAME}}</span></td></tr>\n<tr><td>الحضانة:</td><td><span class=\"var\">{{DAYCARE_LEGAL_NAME}}</span></td></tr>\n<tr><td>الخطة:</td><td><span class=\"var\">{{PLAN}}</span></td></tr>\n<tr><td>تاريخ النفاذ:</td><td><span class=\"var\">{{EFFECTIVE_DATE}}</span></td></tr>\n<tr><td>إصدار القالب:</td><td><span class=\"var\">{{TEMPLATE_VERSION}}</span></td></tr>\n</table></div>\n<p>أُبرمت اتفاقية خدمات الحضانة هذه (المشار إليها فيما بعد بـ <strong>«الاتفاقية»</strong>) في تاريخ النفاذ المبين في جدول الطلب، بين كل من:</p>\n<ol>\n<li><strong>KiddyApp</strong>، شركة مُنشأة وفقًا لقوانين جمهورية مصر العربية، ويقع مقرها المسجل في <code>[العنوان المسجل للمزوّد — مطلوب للتأكيد]</code>، ورقم السجل التجاري <code>[مطلوب للتأكيد]</code>، والرقم الضريبي <code>[مطلوب للتأكيد]</code>، ويمثلها <code>[المفوض بالتوقيع عن المزوّد — مطلوب للتأكيد]</code> (والمشار إليها بـ <strong>«المزوّد»</strong> أو <strong>«KiddyApp»</strong>)؛ و</li>\n</ol>\n<ol>\n<li>الحضانة المحددة في جدول الطلب، والمُبيّن فيه اسمها القانوني وعنوانها المسجل ورقم سجلها التجاري ورقمها الضريبي والمفوض بالتوقيع عنها (والمشار إليها بـ <strong>«الحضانة»</strong>).</li>\n</ol>\n<p>ويُشار إلى المزوّد والحضانة منفردين بـ <strong>«الطرف»</strong> ومجتمعين بـ <strong>«الطرفين»</strong>.</p>\n<h2>التمهيد</h2>\n<p>(أ) يُشغّل المزوّد منصة برمجية لإدارة دور الحضانة، تشمل سجلات الأطفال والحضور والتقارير اليومية والتواصل والسجلات المالية والميزات المرتبطة بها (والمشار إليها بـ <strong>«المنصة»</strong>).</p>\n<p>(ب) تُدير الحضانة نشاطًا لرعاية الأطفال في جمهورية مصر العربية وترغب في استخدام المنصة في عملياتها.</p>\n<p>(ج) يرغب الطرفان في تنظيم الشروط التي يقدم بموجبها المزوّد المنصة والخدمات المرتبطة بها إلى الحضانة.</p>\n<h2>1. التعريفات</h2>\n<p>1.1 في هذه الاتفاقية، وما لم يقتضِ السياق خلاف ذلك:</p>\n<ul>\n<li><strong>«الحساب»</strong> يعني الحساب الإداري الذي يُنشأ للحضانة على المنصة.</li>\n<li><strong>«الشركة التابعة»</strong> يعني أي كيان يسيطر على أحد الطرفين أو يخضع لسيطرته أو يخضع معه لسيطرة مشتركة، ويُقصد بـ «السيطرة» ملكية أكثر من خمسين بالمائة (50%) من حقوق التصويت أو سلطة توجيه الإدارة.</li>\n<li><strong>«القانون الواجب التطبيق»</strong> يعني جميع القوانين واللوائح والمراسيم والقرارات الملزمة السارية في جمهورية مصر العربية، بما في ذلك القانون المدني المصري (القانون رقم 131 لسنة 1948)، وقانون التجارة (القانون رقم 17 لسنة 1999)، وقانون حماية البيانات الشخصية (القانون رقم 151 لسنة 2020) ولائحته التنفيذية، وقانون مكافحة جرائم تقنية المعلومات (القانون رقم 175 لسنة 2018)، وقانون تنظيم التوقيع الإلكتروني (القانون رقم 15 لسنة 2004).</li>\n<li><strong>«المستخدم المُصرّح له»</strong> يعني الشخص الطبيعي الذي تسمح له الحضانة بالوصول إلى الحساب، بما في ذلك المالك والمديرون والمعلمون ومقدمو الرعاية والموظفون.</li>\n<li><strong>«بيانات الأطفال»</strong> يعني البيانات الشخصية المتعلقة بطفل مسجل أو كان مسجلًا في الحضانة، بما في ذلك بيانات الهوية والصحة والحضور والنمو والتعلم.</li>\n<li><strong>«بيانات الأسرة»</strong> يعني البيانات الشخصية المتعلقة بأحد الوالدين أو الوصي أو أفراد الأسرة أو الشخص المُصرّح له بالاستلام.</li>\n<li><strong>«المعلومات السرية»</strong> لها المعنى الوارد في البند 12.</li>\n<li><strong>«ملحق حماية البيانات»</strong> يعني ملحق حماية البيانات المرفق كالملحق 2.</li>\n<li><strong>«تاريخ النفاذ»</strong> يعني التاريخ المبين في جدول الطلب.</li>\n<li><strong>«الرسوم»</strong> يعني المبالغ المستحقة على الحضانة بموجب جدول الطلب.</li>\n<li><strong>«جدول الطلب»</strong> يعني جدول الطلب المرفق كالملحق 1، بعد استكماله وتوقيعه من الطرفين.</li>\n<li><strong>«البيانات الشخصية»</strong> يعني أي بيانات تتعلق بشخص طبيعي محدد أو قابل للتحديد، وفقًا للتعريف الوارد في القانون الواجب التطبيق.</li>\n<li><strong>«محتوى المنصة»</strong> يعني البرمجيات وواجهة المستخدم والنصوص والرسومات والوثائق والمواد الأخرى التي يقدمها المزوّد كجزء من المنصة، باستثناء محتوى الحضانة.</li>\n<li><strong>«محتوى الحضانة»</strong> يعني جميع البيانات والسجلات والصور والوثائق والمواد الأخرى التي ترفعها الحضانة أو مستخدموها المُصرّح لهم إلى المنصة أو ينشئونها عليها، بما في ذلك بيانات الأطفال وبيانات الأسرة.</li>\n<li><strong>«الخدمات»</strong> يعني المنصة وخدمات الدعم الموضحة في البند 3.</li>\n<li><strong>«مدة الاشتراك»</strong> يعني المدة المبينة في جدول الطلب، مضافًا إليها أي فترة تجديد.</li>\n<li><strong>«المستخدم»</strong> يعني مستخدمًا مُصرّحًا له أو أحد الوالدين أو الوصي أو فرد من الأسرة أو شخصًا مُصرّحًا له بالاستلام يصل إلى المنصة من خلال الحضانة.</li>\n</ul>\n<p>1.2 العناوين مُدرجة للتسهيل فقط ولا تؤثر في التفسير. والإشارة إلى بند أو ملحق تعني الإشارة إلى بند أو ملحق من هذه الاتفاقية. ويشمل المفرد الجمع ويشمل الجمع المفرد. وتعبير «بما في ذلك» يعني «بما في ذلك على سبيل المثال لا الحصر».</p>\n<h2>2. ترتيب الأسبقية</h2>\n<p>2.1 في حال وجود تعارض بين الوثائق، يُطبّق ترتيب الأسبقية الآتي:</p>\n<p>(أ) ملحق حماية البيانات، في المسائل المتعلقة بالبيانات الشخصية؛</p>\n<p>(ب) جدول الطلب، في المتغيرات التجارية؛</p>\n<p>(ج) نص هذه الاتفاقية؛</p>\n<p>(د) أي ملحق أو وثيقة أخرى تُدمج بالإشارة.</p>\n<p>2.2 تكون النسخة العربية من هذه الاتفاقية هي المُرجَّحة على النسخة الإنجليزية في حال وجود أي تعارض، ما لم يتفق المزوّد والحضانة على خلاف ذلك كتابةً وبتوقيع الطرفين.</p>\n<h2>3. الخدمات</h2>\n<p>3.1 يمنح المزوّد الحضانة حقًا غير حصري وغير قابل للتحويل وقابلًا للإلغاء في الوصول إلى المنصة واستخدامها خلال مدة الاشتراك، لأغراض الإدارة الداخلية لرعاية الأطفال في الحضانة ووفقًا لهذه الاتفاقية.</p>\n<p>3.2 تشمل الخدمات:</p>\n<p>(أ) الوصول إلى المنصة عبر بوابة الويب وأي تطبيق هاتف محمول يوفره المزوّد؛</p>\n<p>(ب) الميزات المقابلة للخطة المبينة في جدول الطلب؛</p>\n<p>(ج) إعداد الحساب ودعم التهيئة والدعم الفني المعقول خلال ساعات العمل المعتادة للمزوّد؛</p>\n<p>(د) استضافة البيانات والنسخ الاحتياطي وتدابير الأمن الموضحة في البند 11 وملحق حماية البيانات؛ و</p>\n<p>(هـ) أي خدمات إضافية مبينة في جدول الطلب.</p>\n<p>3.3 يجوز للمزوّد تعديل ميزات المنصة أو تحديثها أو استبدالها من وقت لآخر، بشرط ألا يقلل ذلك جوهريًا من الوظائف الأساسية للخطة المشترك بها خلال مدة الاشتراك.</p>\n<p>3.4 يجوز للمزوّد تعليق الوصول إلى المنصة لأغراض الصيانة المجدولة أو الصيانة الطارئة أو لأسباب أمنية. ويقدم المزوّد إخطارًا مسبقًا معقولًا بالصيانة المجدولة حيثما كان ذلك عمليًا.</p>\n<p>3.5 لا تشمل الخدمات:</p>\n<p>(أ) الأجهزة أو الاتصال بالإنترنت أو غيرها من المعدات التي تستخدمها الحضانة أو مستخدموها؛</p>\n<p>(ب) خدمات الرواتب أو المحاسبة أو الضرائب أو الخدمات القانونية؛</p>\n<p>(ج) التحقق من هوية الحضانة أو ترخيصها أو امتثالها التنظيمي؛ أو</p>\n<p>(د) أي خدمة يستلزم القانون الواجب التطبيق أن يؤديها متخصص مرخّص.</p>\n<h2>4. إنشاء الحساب والوصول</h2>\n<p>4.1 ينشئ المزوّد الحساب بعد أن تقدم الحضانة المعلومات المطلوبة في جدول الطلب وتستكمل إجراءات التهيئة لدى المزوّد.</p>\n<p>4.2 يجب على الحضانة تقديم معلومات دقيقة ومحدثة وكاملة، وتحديثها فورًا عند تغيرها.</p>\n<p>4.3 تكون الحضانة مسؤولة عن:</p>\n<p>(أ) جميع الأنشطة التي تجري تحت حسابها وحسابات مستخدميها المُصرّح لهم؛</p>\n<p>(ب) الحفاظ على سرية بيانات تسجيل الدخول؛</p>\n<p>(ج) ضمان أن يكون لكل مستخدم مُصرّح له الدور ومستوى الوصول المناسبان؛</p>\n<p>(د) تعطيل وصول أي مستخدم مُصرّح له يترك الحضانة أو لا يحتاج إلى الوصول فورًا؛ و</p>\n<p>(هـ) إخطار المزوّد دون تأخير غير مبرر بأي وصول غير مُصرّح به أو حادث أمني مشتبه به.</p>\n<p>4.4 يجب على الحضانة عدم مشاركة بيانات اعتماد الحساب بين الأفراد أو السماح بالوصول لأي شخص غير مستخدميها المُصرّح لهم.</p>\n<p>4.5 يجوز للمزوّد الوصول إلى الحساب لتقديم الدعم أو لمنع حادث أمني أو التحقيق فيه أو للامتثال للقانون الواجب التطبيق. ويخطر المزوّد الحضانة قبل هذا الوصول حيثما كان ذلك عمليًا.</p>\n<h2>5. التزامات الحضانة</h2>\n<p>5.1 يجب على الحضانة:</p>\n<p>(أ) استخدام المنصة فقط لأغراض إدارة رعاية الأطفال المشروعة؛</p>\n<p>(ب) الحصول على جميع التراخيص والتصاريح والسجلات اللازمة لتشغيل حضانتها والاحتفاظ بها؛</p>\n<p>(ج) الحصول على جميع الموافقات وتقديم جميع الإخطارات اللازمة لجمع ومعالجة بيانات الأطفال وبيانات الأسرة من خلال المنصة؛</p>\n<p>(د) ضمان أن تكون بيانات الأطفال وبيانات الأسرة التي تقدمها دقيقة ومجمعة بشكل قانوني؛</p>\n<p>(هـ) الامتثال للقانون الواجب التطبيق، بما في ذلك متطلبات حماية الطفل والصحة والسلامة والعمل وحماية البيانات؛</p>\n<p>(و) تعيين شخص مسؤول للتواصل بشأن الحساب وبشأن مسائل حماية البيانات؛ و</p>\n<p>(ز) التعاون بشكل معقول مع المزوّد في ما يتعلق بالأمن والمراجعات والاستفسارات التنظيمية.</p>\n<p>5.2 تتحمل الحضانة وحدها مسؤولية رعاية الأطفال في مركزها والإشراف عليهم وصحتهم وسلامتهم وتعليمهم. والمنصة أداة إدارية ولا تحل محل التقدير المهني في رعاية الأطفال أو الالتزامات القانونية للحضانة.</p>\n<p>5.3 يجب على الحضانة عدم استخدام المنصة لتسجيل أو توزيع مواد غير قانونية أو تشهيرية أو تمييزية أو ضارة بطفل.</p>\n<h2>6. الاستخدام المقبول</h2>\n<p>6.1 يجب على الحضانة عدم القيام، وضمان عدم قيام مستخدميها، بما يلي:</p>\n<p>(أ) نسخ المنصة أو تعديلها أو ترجمتها أو إجراء هندسة عكسية لها أو فك تجميعها أو محاولة استخلاص شفرتها المصدرية، إلا بالقدر الذي يسمح به القانون الواجب التطبيق؛</p>\n<p>(ب) إعادة بيع المنصة أو ترخيصها من الباطن أو تأجيرها أو تقديمها لطرف ثالث كخدمة؛</p>\n<p>(ج) التدخل في أمن المنصة أو سلامتها أو أدائها؛</p>\n<p>(د) رفع فيروسات أو برمجيات خبيثة أو أي شفرات ضارة أخرى؛</p>\n<p>(هـ) استخدام المنصة لإرسال رسائل تجارية غير مطلوبة أو لجمع البيانات؛</p>\n<p>(و) الوصول إلى بيانات حضانة أخرى أو مستخدم آخر دون تصريح؛</p>\n<p>(ز) استخدام المنصة بما يخالف خصوصية طفل أو أسرة أو حقوقهما؛ أو</p>\n<p>(ح) استخدام المنصة لأي غرض غير قانوني بموجب القانون الواجب التطبيق.</p>\n<p>6.2 يجوز للمزوّد التحقيق في حالات الاشتباه في انتهاك هذا البند 6، ويجوز له تعليق الوصول أو إنهاؤه حيثما شكل الانتهاك خطرًا أمنيًا أو قانونيًا أو خطرًا على سلامة الأطفال.</p>\n<h2>7. الرسوم والفوترة والدفع</h2>\n<p>7.1 تدفع الحضانة الرسوم المبينة في جدول الطلب بالجنيه المصري (EGP)، خالية من أي مقاصة أو خصم، إلا بالقدر الذي يقتضيه القانون الواجب التطبيق.</p>\n<p>7.2 يعتمد نموذج الفوترة على الخطة المختارة في جدول الطلب:</p>\n<p>(أ) <strong>الخطة التجريبية (Demo).</strong> لا تُستحق رسوم عن فترة العرض التجريبي المبينة في جدول الطلب. ولا يجوز للمزوّد إنهاء فترة العرض التجريبي أو تحويلها إلى خطة مدفوعة إلا وفقًا لما هو مبين في جدول الطلب أو باتفاق كتابي.</p>\n<p>(ب) <strong>الخطة الشهرية (Monthly).</strong> المبلغ الشهري هو السعر الشهري المبين في جدول الطلب، مضافًا إليه سعر كل طفل نشط يزيد على حد الأطفال المجانيين المبين في جدول الطلب.</p>\n<p>(ج) <strong>الخطة السنوية (Annual).</strong> يُستحق المبلغ السنوي المبين في جدول الطلب مرة واحدة عن كل فترة فوترة مدتها اثنا عشر شهرًا.</p>\n<p>7.3 تبدأ دورة الفوترة الخاصة بالحضانة في التاريخ المبين في جدول الطلب. وما لم ينص جدول الطلب على خلاف ذلك، تُصدر الفاتورة في نهاية كل دورة فوترة وتكون مستحقة السداد بحلول اليوم الخامس (5) من الشهر التالي لتاريخ الفاتورة.</p>\n<p>7.4 لا تشمل الرسوم ضريبة القيمة المضافة أو أي ضرائب أخرى واجبة التطبيق، ما لم ينص جدول الطلب على أنها شاملة. وتتحمل الحضانة أي ضرائب أو رسوم أو استقطاعات يقتضيها القانون الواجب التطبيق، باستثناء الضرائب المفروضة على دخل المزوّد.</p>\n<p>7.5 يجوز للمزوّد تعديل الرسوم لفترة التجديد بإخطار كتابي إلى الحضانة قبل ستين (60) يومًا على الأقل من نهاية مدة الاشتراك الحالية. وإذا لم تقبل الحضانة التعديل، يجوز لها إنهاء هذه الاتفاقية اعتبارًا من نهاية مدة الاشتراك الحالية بإخطار كتابي يُقدم قبل تاريخ التجديد.</p>\n<p>7.6 يصدر المزوّد الفواتير إلكترونيًا ويجوز له تسليمها بالبريد الإلكتروني أو عبر المنصة. ويجب على الحضانة تقديم جهة اتصال صحيحة للفوترة وبريد إلكتروني صحيح للفوترة.</p>\n<p>7.7 تُسدد جميع المدفوعات بالطريقة المبينة في جدول الطلب أو التي يخطر بها المزوّد كتابةً، بما في ذلك التحويل البنكي أو أي رابط دفع يوفره المزوّد.</p>\n<h2>8. التأخر في السداد والتعليق</h2>\n<p>8.1 إذا لم تسدد الحضانة فاتورة غير متنازع عليها بحلول تاريخ استحقاقها، يجوز للمزوّد فرض فائدة تأخير بالسعر الذي يسمح به القانون الواجب التطبيق من تاريخ الاستحقاق حتى السداد.</p>\n<p>8.2 إذا بقيت فاتورة غير متنازع عليها غير مسددة لمدة تزيد على عشرة (10) أيام عمل بعد تاريخ استحقاقها، يجوز للمزوّد تعليق الوصول إلى المنصة بعد إخطار كتابي إلى الحضانة قبل خمسة (5) أيام عمل على الأقل.</p>\n<p>8.3 خلال فترة التعليق، يحفظ المزوّد بيانات الحضانة للمدة المبينة في ملحق حماية البيانات. ولا يعفي التعليق الحضانة من التزامها بسداد الرسوم المستحقة.</p>\n<p>8.4 يستعيد المزوّد الوصول فورًا بعد سداد الحضانة لجميع المبالغ المستحقة وأي رسوم تأخير واجبة التطبيق.</p>\n<p>8.5 إذا نازعت الحضانة في فاتورة بحسن نية، وجب عليها إخطار المزوّد كتابةً خلال عشرة (10) أيام عمل من تاريخ الفاتورة، مع بيان تفاصيل النزاع. ويظل الجزء غير المتنازع عليه مستحق السداد.</p>\n<h2>9. المدة والتجديد</h2>\n<p>9.1 تبدأ هذه الاتفاقية في تاريخ النفاذ وتستمر لمدة الاشتراك المبينة في جدول الطلب.</p>\n<p>9.2 ما لم ينص جدول الطلب على خلاف ذلك:</p>\n<p>(أ) تتجدد الخطة الشهرية تلقائيًا لفترات متتالية مدتها شهر واحد؛</p>\n<p>(ب) تتجدد الخطة السنوية تلقائيًا لفترات متتالية مدتها اثنا عشر شهرًا؛ و</p>\n<p>(ج) لا تتجدد الخطة التجريبية وتنتهي بانتهاء فترة العرض التجريبي ما لم يتفق الطرفان كتابةً على خطة مدفوعة.</p>\n<p>9.3 يجوز لأي من الطرفين منع التجديد بإخطار كتابي قبل ثلاثين (30) يومًا على الأقل من نهاية مدة الاشتراك الحالية، ما لم ينص جدول الطلب على فترة إخطار مختلفة.</p>\n<p>9.4 يجوز للمزوّد رفض تجديد هذه الاتفاقية بإخطار كتابي قبل ستين (60) يومًا على الأقل من نهاية مدة الاشتراك الحالية.</p>\n<h2>10. الإنهاء</h2>\n<p>10.1 يجوز لأي من الطرفين إنهاء هذه الاتفاقية فورًا بإخطار كتابي إذا:</p>\n<p>(أ) ارتكب الطرف الآخر إخلالًا جوهريًا بهذه الاتفاقية ولم يعالجه خلال ثلاثين (30) يومًا من استلام إخطار كتابي يوضح الإخلال؛ أو</p>\n<p>(ب) أصبح الطرف الآخر معسرًا أو دخل في تصفية أو خضع لإجراء إفلاس أو إجراء مماثل أو توقف عن مزاولة النشاط.</p>\n<p>10.2 يجوز للمزوّد إنهاء هذه الاتفاقية فورًا بإخطار كتابي إذا:</p>\n<p>(أ) استخدمت الحضانة المنصة بطريقة تخلق خطرًا جسيمًا على طفل أو على المنصة أو على أي شخص آخر؛</p>\n<p>(ب) كررت الحضانة انتهاك البند 6 بعد إنذار كتابي؛ أو</p>\n<p>(ج) لم تحتفظ الحضانة بترخيص أو سجل مطلوب لتشغيل حضانتها.</p>\n<p>10.3 يجوز للحضانة إنهاء هذه الاتفاقية فورًا بإخطار كتابي إذا ارتكب المزوّد إخلالًا جوهريًا بملحق حماية البيانات أو وقع حادث أمني يؤثر جوهريًا على بيانات الحضانة ولم يُعالج خلال فترة معقولة.</p>\n<p>10.4 عند الإنهاء أو انتهاء المدة:</p>\n<p>(أ) ينتهي حق الحضانة في الوصول إلى المنصة؛</p>\n<p>(ب) تسدد الحضانة جميع الرسوم المستحقة حتى تاريخ الإنهاء الفعلي؛</p>\n<p>(ج) يتيح المزوّد للحضانة تصدير بياناتها بتنسيق قياسي لمدة ثلاثين (30) يومًا، ما لم ينص ملحق حماية البيانات على فترة مختلفة؛</p>\n<p>(د) بعد فترة التصدير، يحذف المزوّد بيانات الحضانة أو يجعلها مجهولة الهوية وفقًا لملحق حماية البيانات؛ و</p>\n<p>(هـ) يعيد كل طرف أو يتلف المعلومات السرية للطرف الآخر، إلا حيث يقتضي القانون الواجب التطبيق الاحتفاظ بها.</p>\n<p>10.5 تستمر البنود التي يقتضي طبيعتها الاستمرار بعد الإنهاء، بما في ذلك البنود 11 و12 و13 و14 و15 و16 و18 و19.</p>\n<h2>11. حماية البيانات</h2>\n<p>11.1 يلتزم الطرفان بالقانون الواجب التطبيق بشأن حماية البيانات الشخصية، بما في ذلك قانون حماية البيانات الشخصية (القانون رقم 151 لسنة 2020) ولائحته التنفيذية.</p>\n<p>11.2 لأغراض ملحق حماية البيانات:</p>\n<p>(أ) تكون الحضانة هي المتحكم في بيانات الأطفال وبيانات الأسرة؛</p>\n<p>(ب) يكون المزوّد هو المعالج لبيانات الأطفال وبيانات الأسرة؛ و</p>\n<p>(ج) يعالج المزوّد بيانات الأطفال وبيانات الأسرة فقط بناءً على تعليمات الحضانة الموثقة وحسب ما يقتضيه القانون الواجب التطبيق.</p>\n<p>11.3 يشكل ملحق حماية البيانات جزءًا لا يتجزأ من هذه الاتفاقية، ويسود على هذه الاتفاقية في حال وجود تعارض يتعلق بالبيانات الشخصية.</p>\n<p>11.4 تتحمل الحضانة مسؤولية الحصول على أساس قانوني لمعالجة بيانات الأطفال وبيانات الأسرة، بما في ذلك أي موافقة مطلوبة من أحد الوالدين أو الوصي، ومسؤولية تقديم أي إخطار خصوصية مطلوب.</p>\n<p>11.5 يطبق المزوّد تدابير فنية وتنظيمية مناسبة لحماية البيانات الشخصية، على النحو الموضح في ملحق حماية البيانات.</p>\n<p>11.6 يخطر المزوّد الحضانة دون تأخير غير مبرر بعد علمه بأي اختراق للبيانات الشخصية يؤثر على بيانات الحضانة، ويقدم المعلومات المعقولة اللازمة لكي تفي الحضانة بالتزامات الإخطار الخاصة بها.</p>\n<p>11.7 يجوز للمزوّد استخدام معالجين من الباطن على النحو الموضح في ملحق حماية البيانات. ويظل المزوّد مسؤولًا أمام الحضانة عن أداء هؤلاء المعالجين من الباطن لالتزامات حماية البيانات.</p>\n<h2>12. السرية</h2>\n<p>12.1 <strong>«المعلومات السرية»</strong> يعني أي معلومات يفصح عنها أحد الطرفين للطرف الآخر في سياق هذه الاتفاقية وتكون موسومة بأنها سرية أو يفهم الشخص المعقول أنها سرية، بما في ذلك الشروط التجارية والأسعار وقوائم العملاء والمعلومات الفنية والمعلومات الأمنية وبيانات الأطفال وبيانات الأسرة ومحتويات المنصة.</p>\n<p>12.2 يجب على كل طرف:</p>\n<p>(أ) استخدام المعلومات السرية فقط لأغراض هذه الاتفاقية؛</p>\n<p>(ب) حماية المعلومات السرية بعناية معقولة على الأقل؛</p>\n<p>(ج) الإفصاح عن المعلومات السرية فقط لموظفيه ومسؤوليه ومستشاريه المهنيين ومتعهديه الذين يحتاجون إلى معرفتها ويلتزمون بالتزامات سرية لا تقل حماية عن هذا البند؛ و</p>\n<p>(د) عدم الإفصاح عن المعلومات السرية لأي شخص آخر دون موافقة كتابية مسبقة من الطرف المفصح، إلا حسب ما يقتضيه القانون الواجب التطبيق أو جهة مختصة.</p>\n<p>12.3 لا تشمل المعلومات السرية المعلومات التي:</p>\n<p>(أ) تكون علنية أو تصبح علنية دون إخلال بهذه الاتفاقية؛</p>\n<p>(ب) كانت معروفة بشكل قانوني للطرف المتلقي قبل الإفصاح؛</p>\n<p>(ج) تُستلم بشكل قانوني من طرف ثالث دون واجب سرية؛ أو</p>\n<p>(د) تُطوَّر بشكل مستقل دون استخدام المعلومات السرية.</p>\n<p>12.4 إذا كان على أحد الطرفين الإفصاح عن معلومات سرية بموجب القانون أو لجهة مختصة، وجب عليه، حيثما كان ذلك قانونيًا وعمليًا، إخطار الطرف الآخر قبل الإفصاح، وألا يفصح إلا عن الحد الأدنى المطلوب.</p>\n<p>12.5 تستمر التزامات السرية خلال مدة الاتفاقية ولمدة ثلاث (3) سنوات بعد الإنهاء أو انتهاء المدة. وتظل الأسرار التجارية والبيانات الشخصية محمية طالما احتفظت بهذه الصفة بموجب القانون الواجب التطبيق.</p>\n<h2>13. الملكية الفكرية</h2>\n<p>13.1 يملك المزوّد ومرخّصوه جميع الحقوق في المنصة ومحتوى المنصة وأي تحسينات أو تعديلات أو أعمال مشتقة من المنصة. ولا تُمنح أي حقوق إلا كما هو منصوص عليه صراحةً في هذه الاتفاقية.</p>\n<p>13.2 تملك الحضانة ومرخّصوها جميع الحقوق في محتوى الحضانة. وتمنح الحضانة المزوّد ترخيصًا غير حصري وخاليًا من royalties لاستضافة محتوى الحضانة وتخزينه ونسخه ومعالجته ونقله وعرضه فقط لتقديم الخدمات وحسب ما يقتضيه القانون الواجب التطبيق.</p>\n<p>13.3 تمنح الحضانة المزوّد ترخيصًا غير حصري وخاليًا من royalties لاستخدام الملاحظات والاقتراحات والأفكار التي تقدمها الحضانة لتحسين المنصة، بشرط ألا يحدد المزوّد هوية الحضانة أو يفصح عن معلوماتها السرية.</p>\n<p>13.4 يجب على المزوّد عدم استخدام اسم الحضانة أو شعارها أو علاماتها التجارية في التسويق العام دون موافقة كتابية مسبقة من الحضانة، باستثناء أن للمزوّد أن يحدد الحضانة كعميل في قائمة خاصة تُقدم لعميل محتمل على أساس سري.</p>\n<p>13.5 يجب على الحضانة عدم إزالة أي إشعار ملكية على المنصة أو إخفائه أو تعديله.</p>\n<h2>14. الإقرارات والضمانات وإخلاء المسؤولية</h2>\n<p>14.1 يقر كل طرف بأنه يملك الأهلية لإبرام هذه الاتفاقية وأن ممثله مفوض بشكل صحيح.</p>\n<p>14.2 يقر المزوّد ويضمن ما يلي:</p>\n<p>(أ) أنه سيقدم الخدمات بمهارة وعناية معقولتين ووفقًا لهذه الاتفاقية؛</p>\n<p>(ب) أن المنصة ستتوافق جوهريًا مع الوثائق التي يقدمها المزوّد؛ و</p>\n<p>(ج) أنه سيبذل جهودًا معقولة لتصحيح العيوب القابلة لإعادة الإنتاج التي تبلغ بها الحضانة.</p>\n<p>14.3 تقر الحضانة وتضمن ما يلي:</p>\n<p>(أ) أنها تحتفظ بجميع التراخيص والتصاريح اللازمة لتشغيل حضانتها؛</p>\n<p>(ب) أن لديها أساسًا قانونيًا لبيانات الأطفال وبيانات الأسرة التي تقدمها إلى المنصة؛ و</p>\n<p>(ج) أن استخدامها للمنصة سيمتثل للقانون الواجب التطبيق.</p>\n<p>14.4 باستثناء ما هو منصوص عليه صراحةً في هذه الاتفاقية، لا يضمن المزوّد أن تكون المنصة غير منقطعة أو خالية من الأخطاء أو خالية من الشفرات الضارة. ولا يضمن المزوّد أي نتيجة من استخدام المنصة.</p>\n<p>14.5 المزوّد غير مسؤول عن دقة البيانات التي تدخلها الحضانة أو مستخدموها، أو عن أي قرار تتخذه الحضانة باستخدام المنصة.</p>\n<p>14.6 لا شيء في هذه الاتفاقية يستبعد أو يحد من أي ضمان أو مسؤولية لا يجوز استبعادها أو الحد منها بموجب القانون الواجب التطبيق.</p>\n<h2>15. تحديد المسؤولية</h2>\n<p>15.1 مع مراعاة البند 15.3، تقتصر المسؤولية الإجمالية لكل طرف بموجب هذه الاتفاقية، سواء كانت تعاقدية أو تقصيرية أو ناشئة عن الإهمال أو غير ذلك، على المبلغ المبين في جدول الطلب كحد أقصى للمسؤولية.</p>\n<p>15.2 مع مراعاة البند 15.3، لا يكون أي طرف مسؤولًا عن الخسائر غير المباشرة أو التبعية أو خسارة الأرباح أو خسارة الإيرادات أو خسارة الأعمال أو خسارة السمعة أو خسارة البيانات، إلا بالقدر الناتج عن إخلال الطرف الآخر بالبند 11 أو البند 12.</p>\n<p>15.3 لا شيء في هذه الاتفاقية يحد أو يستبعد المسؤولية عن:</p>\n<p>(أ) الاحتيال أو سوء السلوك المتعمد؛</p>\n<p>(ب) الوفاة أو الإصابة الشخصية الناتجة عن الإهمال؛</p>\n<p>(ج) الإخلال بالتزامات السرية أو حماية البيانات، بالقدر الذي يسمح به القانون الواجب التطبيق؛</p>\n<p>(د) انتهاك حقوق الملكية الفكرية للطرف الآخر؛ أو</p>\n<p>(هـ) أي مسؤولية لا يجوز الحد منها أو استبعادها بموجب القانون الواجب التطبيق.</p>\n<p>15.4 يتفق الطرفان على أن التحديد الوارد في البند 15.1 معقول بالنظر إلى الرسوم وطبيعة الخدمات وتوزيع المخاطر بين الطرفين.</p>\n<h2>16. التعويض</h2>\n<p>16.1 يعوّض المزوّد الحضانة عن أي مطالبة من طرف ثالث بأن المنصة، كما يقدمها المزوّد وتُستخدم وفقًا لهذه الاتفاقية، تنتهك حقًا من حقوق النشر أو العلامات التجارية أو الأسرار التجارية لذلك الطرف الثالث، بشرط أن:</p>\n<p>(أ) تخطر الحضانة المزوّد كتابةً فورًا؛</p>\n<p>(ب) تمنح الحضانة المزوّد السيطرة الكاملة على الدفاع والتسوية؛ و</p>\n<p>(ج) تقدم الحضانة تعاونًا معقولًا على نفقة المزوّد.</p>\n<p>16.2 إذا قُدمت مطالبة بانتهاك أو كان ذلك محتملًا، يجوز للمزوّد، حسب اختياره:</p>\n<p>(أ) الحصول على حق للحضانة لمواصلة استخدام المنصة؛</p>\n<p>(ب) تعديل المنصة بحيث لا تنتهك الحقوق مع الاحتفاظ بوظائف مكافئة جوهريًا؛ أو</p>\n<p>(ج) إنهاء هذه الاتفاقية واسترداد أي رسوم مدفوعة مسبقًا عن الجزء المتبقي من مدة الاشتراك.</p>\n<p>16.3 تعوّض الحضانة المزوّد عن أي مطالبة من طرف ثالث تنشأ عن:</p>\n<p>(أ) محتوى الحضانة، بما في ذلك مطالبة بأن الحضانة لم يكن لها الحق في تقديمه؛</p>\n<p>(ب) معالجة الحضانة لبيانات الأطفال أو بيانات الأسرة بما يخالف القانون الواجب التطبيق؛ أو</p>\n<p>(ج) إخلال الحضانة بالبند 5 أو البند 6.</p>\n<p>16.4 يحدد هذا البند 16 المسؤولية الكاملة للمزوّد، والسبيل الكامل للحضانة، فيما يتعلق بانتهاك الملكية الفكرية.</p>\n<h2>17. القوة القاهرة</h2>\n<p>17.1 لا يكون أي طرف مسؤولًا عن فشل أو تأخر في أداء التزاماته بسبب حدث خارج عن سيطرته المعقولة، بما في ذلك الكوارث الطبيعية أو الحريق أو الفيضان أو الأوبئة أو الحرب أو الاضطرابات المدنية أو الإضراب أو إجراءات الحكومة أو انقطاع خدمات الاتصالات العامة أو الكهرباء أو انقطاع الإنترنت على نطاق واسع.</p>\n<p>17.2 يجب على الطرف المتأثر إخطار الطرف الآخر فورًا وبذل جهود معقولة للتخفيف من الأثر. وإذا استمر الحدث أكثر من ثلاثين (30) يومًا، جاز لأي من الطرفين إنهاء هذه الاتفاقية بإخطار كتابي.</p>\n<p>17.3 لا يعفي هذا البند الحضانة من سداد الرسوم مقابل الخدمات المقدمة بالفعل.</p>\n<h2>18. الإخطارات</h2>\n<p>18.1 يجب أن تكون الإخطارات بموجب هذه الاتفاقية كتابية وأن تُسلَّم باليد أو بالبريد السريع أو بالبريد المسجل أو بالبريد الإلكتروني إلى العناوين المبينة في جدول الطلب.</p>\n<p>18.2 يُعتبر الإخطار مستلمًا:</p>\n<p>(أ) عند التسليم، إذا سُلّم باليد أو بالبريد السريع؛</p>\n<p>(ب) بعد ثلاثة (3) أيام عمل من الإرسال، إذا أُرسل بالبريد المسجل؛ أو</p>\n<p>(ج) في يوم العمل التالي، إذا أُرسل بالبريد الإلكتروني قبل الساعة 5:00 مساءً بتوقيت القاهرة ولم يصل إشعار بفشل التسليم.</p>\n<p>18.3 يجوز لأي طرف تغيير عنوان الإخطار الخاص به بإخطار كتابي إلى الطرف الآخر.</p>\n<h2>19. القانون الواجب التطبيق وتسوية المنازعات</h2>\n<p>19.1 تخضع هذه الاتفاقية لقوانين جمهورية مصر العربية.</p>\n<p>19.2 يحاول الطرفان أولًا تسوية أي نزاع بحسن نية من خلال مفاوضات بين ممثلين مفوضين لمدة ثلاثين (30) يومًا على الأقل بعد إخطار كتابي بالنزاع.</p>\n<p>19.3 إذا لم يُسوَّ النزاع بالمفاوضات، تختص المحاكم المختصة الواقعة في القاهرة بجمهورية مصر العربية اختصاصًا حصريًا، ما لم يتفق الطرفان كتابةً على التحكيم.</p>\n<p>19.4 لا يمنع هذا البند أي طرف من طلب تدبير مؤقت عاجل من محكمة مختصة.</p>\n<h2>20. الاتفاق الكامل</h2>\n<p>20.1 تشكل هذه الاتفاقية وملاحقها الاتفاق الكامل بين الطرفين بشأن موضوعها، وتحل محل جميع المناقشات والمقترحات والإقرارات السابقة.</p>\n<p>20.2 لا يعتمد أي طرف على أي بيان أو إقرار أو ضمان غير منصوص عليه صراحةً في هذه الاتفاقية، إلا في حالة الاحتيال.</p>\n<h2>21. التعديلات</h2>\n<p>21.1 يجب أن يكون أي تعديل على هذه الاتفاقية كتابيًا وموقعًا من ممثلين مفوضين لكلا الطرفين.</p>\n<p>21.2 يجوز للمزوّد تحديث ميزات المنصة ووثائقها دون تعديل هذه الاتفاقية، بشرط ألا يقلل التحديث جوهريًا من الوظائف المشترك بها أو يزيد الرسوم.</p>\n<h2>22. التنازل</h2>\n<p>22.1 لا يجوز لأي طرف التنازل عن هذه الاتفاقية أو نقلها، كليًا أو جزئيًا، دون موافقة كتابية مسبقة من الطرف الآخر، باستثناء أن للطرف أن يتنازل عنها لشركة تابعة أو لخلف في سياق اندماج أو استحواذ أو بيع معظم أصوله، بشرط أن يتحمل المتنازل له التزامات الطرف المتنازل.</p>\n<p>22.2 يكون أي تنازل مخالف لهذا البند باطلًا.</p>\n<h2>23. اللغة والنسخ</h2>\n<p>23.1 تُنفَّذ هذه الاتفاقية بنسختين، عربية وإنجليزية. وللنسختين ترقيم بنود واحد.</p>\n<p>23.2 تكون النسخة العربية هي المُرجَّحة في حال وجود أي تعارض، ما لم يتفق المزوّد والحضانة على خلاف ذلك كتابةً وبتوقيع الطرفين. وتُقدَّم النسخة الإنجليزية للتسهيل ولأي حضانة تعمل باللغة الإنجليزية.</p>\n<p>23.3 إذا كانت هناك حاجة إلى ترجمة معتمدة لمحكمة أو جهة أو سجل، جاز للحضانة الحصول عليها على نفقتها. ولا تغير الترجمة المعتمدة النسخة المُرجَّحة ما لم يتفق الطرفان كتابةً.</p>\n<p>23.4 يجوز توقيع هذه الاتفاقية في نسخ متعددة، بما في ذلك التوقيع الإلكتروني وفقًا لقانون تنظيم التوقيع الإلكتروني (القانون رقم 15 لسنة 2004). وتُعد كل نسخة أصلًا، وتشكل جميع النسخ معًا اتفاقية واحدة.</p>\n<h2>24. أحكام عامة</h2>\n<p>24.1 <strong>قابلية الفصل.</strong> إذا تبيّن أن حكمًا من أحكام هذه الاتفاقية غير صالح أو غير قابل للتنفيذ، تستمر الأحكام المتبقية سارية، ويستبدل الطرفان الحكم غير الصالح بحكم صالح يعكس نيتهما الأصلية.</p>\n<p>24.2 <strong>التنازل عن الحق.</strong> لا يُعد عدم ممارسة حق أو التأخر في ممارسته تنازلًا عن ذلك الحق. ويجب أن يكون التنازل كتابيًا ويقتصر على المسألة المحددة المبينة فيه.</p>\n<p>24.3 <strong>لا شراكة.</strong> لا تنشئ هذه الاتفاقية شراكة أو مشروعًا مشتركًا أو وكالة أو علاقة عمل بين الطرفين.</p>\n<p>24.4 <strong>حقوق الأطراف الثالثة.</strong> لا يحق لأي شخص ليس طرفًا في هذه الاتفاقية تنفيذها، إلا كما هو منصوص عليه صراحةً.</p>\n<p>24.5 <strong>ضمانات إضافية.</strong> يلتزم كل طرف بما يلزم بشكل معقول لتنفيذ هذه الاتفاقية.</p>\n<p>24.6 <strong>التكاليف.</strong> يتحمل كل طرف تكاليفه الخاصة للتفاوض وإبرام هذه الاتفاقية، ما لم ينص جدول الطلب على خلاف ذلك.</p>\n<section class=\"annex\" id=\"annex-1\">\n<h1>جدول الطلب — الملحق 1</h1>\n<p class=\"note\">يُكمل هذا الجدول الاتفاقية. وإذا كان أي حقل فارغًا أو موسومًا بعبارة «مطلوب للتأكيد»، فلا تكون الاتفاقية جاهزة للتوقيع.</p>\n<h2>أ. الأطراف</h2>\n<table class=\"order\"><thead><tr><th>المعرّف</th><th>الحقل</th><th>القيمة</th></tr></thead><tbody><tr><td>A1</td><td>مرجع العقد</td><td><span class=\"var\">{{CONTRACT_REF}}</span></td></tr><tr><td>A2</td><td>الاسم القانوني للمزوّد</td><td><span class=\"var\">{{PROVIDER_LEGAL_NAME}}</span></td></tr><tr><td>A3</td><td>رقم السجل التجاري للمزوّد</td><td><span class=\"var\">{{PROVIDER_CRN}}</span></td></tr><tr><td>A4</td><td>الرقم الضريبي للمزوّد</td><td><span class=\"var\">{{PROVIDER_TAX_ID}}</span></td></tr><tr><td>A5</td><td>العنوان المسجل للمزوّد</td><td><span class=\"var\">{{PROVIDER_ADDRESS}}</span></td></tr><tr><td>A6</td><td>بريد إخطارات المزوّد</td><td><span class=\"var\">{{PROVIDER_NOTICE_EMAIL}}</span></td></tr><tr><td>A7</td><td>المفوض بالتوقيع عن المزوّد</td><td><span class=\"var\">{{PROVIDER_SIGNATORY}}</span></td></tr><tr><td>A8</td><td>الاسم القانوني للحضانة</td><td><span class=\"var\">{{DAYCARE_LEGAL_NAME}}</span></td></tr><tr><td>A9</td><td>الاسم التجاري للحضانة</td><td><span class=\"var\">{{DAYCARE_TRADE_NAME}}</span></td></tr><tr><td>A10</td><td>رقم السجل التجاري للحضانة</td><td><span class=\"var\">{{DAYCARE_CRN}}</span></td></tr><tr><td>A11</td><td>الرقم الضريبي للحضانة</td><td><span class=\"var\">{{DAYCARE_TAX_ID}}</span></td></tr><tr><td>A12</td><td>العنوان المسجل للحضانة</td><td><span class=\"var\">{{DAYCARE_ADDRESS}}</span></td></tr><tr><td>A13</td><td>بريد فوترة الحضانة</td><td><span class=\"var\">{{DAYCARE_BILLING_EMAIL}}</span></td></tr><tr><td>A14</td><td>بريد إخطارات الحضانة</td><td><span class=\"var\">{{DAYCARE_NOTICE_EMAIL}}</span></td></tr><tr><td>A15</td><td>المفوض بالتوقيع عن الحضانة</td><td><span class=\"var\">{{DAYCARE_SIGNATORY}}</span></td></tr><tr><td>A16</td><td>منصب المفوض بالتوقيع</td><td><span class=\"var\">{{DAYCARE_SIGNATORY_TITLE}}</span></td></tr><tr><td>A17</td><td>مسؤول حماية البيانات بالحضانة</td><td><span class=\"var\">{{DAYCARE_DP_CONTACT}}</span></td></tr><tr><td>A18</td><td>حساب/نطاق الحضانة</td><td><span class=\"var\">{{DAYCARE_SUBDOMAIN}}</span></td></tr></tbody></table>\n<h2>ب. الشروط التجارية</h2>\n<table class=\"order\"><thead><tr><th>المعرّف</th><th>الحقل</th><th>القيمة</th></tr></thead><tbody><tr><td>B1</td><td>الخطة (demo / monthly / annual)</td><td><span class=\"var\">{{PLAN}}</span></td></tr><tr><td>B2</td><td>السعر الشهري (جنيه مصري)</td><td><span class=\"var\">{{MONTHLY_RATE_EGP}}</span></td></tr><tr><td>B3</td><td>سعر الطفل الإضافي (جنيه مصري)</td><td><span class=\"var\">{{PER_CHILD_RATE_EGP}}</span></td></tr><tr><td>B4</td><td>حد الأطفال المجانيين</td><td><span class=\"var\">{{FREE_CHILD_THRESHOLD}}</span></td></tr><tr><td>B5</td><td>المبلغ السنوي (جنيه مصري)</td><td><span class=\"var\">{{ANNUAL_AMOUNT_EGP}}</span></td></tr><tr><td>B6</td><td>العملة</td><td><span class=\"var\">{{CURRENCY}}</span></td></tr><tr><td>B7</td><td>بداية دورة الفوترة</td><td><span class=\"var\">{{TERM_START}}</span></td></tr><tr><td>B8</td><td>تاريخ النفاذ</td><td><span class=\"var\">{{EFFECTIVE_DATE}}</span></td></tr><tr><td>B9</td><td>مدة الاشتراك الأولية</td><td><span class=\"var\">{{INITIAL_TERM}}</span></td></tr><tr><td>B10</td><td>مدة التجديد</td><td><span class=\"var\">{{RENEWAL_TERM}}</span></td></tr><tr><td>B11</td><td>فترة الإخطار لعدم التجديد (أيام)</td><td><span class=\"var\">{{NOTICE_PERIOD_DAYS}}</span></td></tr><tr><td>B12</td><td>فترة العرض التجريبي (إذا كانت B1 = demo)</td><td><span class=\"var\">{{DEMO_PERIOD}}</span></td></tr><tr><td>B13</td><td>خطة التحويل بعد العرض التجريبي</td><td><span class=\"var\">{{DEMO_CONVERSION_PLAN}}</span></td></tr><tr><td>B14</td><td>الحد الأقصى للمسؤولية (جنيه مصري)</td><td><span class=\"var\">{{LIABILITY_CAP_EGP}}</span></td></tr><tr><td>B15</td><td>الحد الأقصى للمسؤولية كتابةً</td><td><span class=\"var\">{{LIABILITY_CAP_WORDS}}</span></td></tr><tr><td>B16</td><td>معالجة ضريبة القيمة المضافة</td><td><span class=\"var\">{{VAT_TREATMENT}}</span></td></tr><tr><td>B17</td><td>طريقة الدفع</td><td><span class=\"var\">{{PAYMENT_METHOD}}</span></td></tr><tr><td>B18</td><td>يوم استحقاق الفاتورة</td><td><span class=\"var\">{{INVOICE_DUE_DAY}}</span></td></tr><tr><td>B19</td><td>فائدة التأخير</td><td><span class=\"var\">{{LATE_INTEREST}}</span></td></tr><tr><td>B20</td><td>المحاكم المختصة</td><td><span class=\"var\">{{COURTS}}</span></td></tr><tr><td>B21</td><td>اللغة المُرجَّحة</td><td><span class=\"var\">{{PREVAILING_LANGUAGE}}</span></td></tr><tr><td>B22</td><td>خدمات إضافية</td><td><span class=\"var\">{{ADDITIONAL_SERVICES}}</span></td></tr></tbody></table>\n<h3>ج. قواعد الفوترة</h3>\n<p><strong>الخطة الشهرية.</strong> المبلغ الشهري هو B2 مضافًا إليه B3 عن كل طفل نشط يزيد على B4. ويُحتسب الطفل إذا كان نشطًا في أي وقت خلال دورة الفوترة.</p>\n<p><strong>الخطة السنوية.</strong> يُستحق المبلغ السنوي B5 مرة واحدة عن كل فترة اثني عشر شهرًا.</p>\n<p><strong>الخطة التجريبية.</strong> لا تُستحق رسوم خلال B12.</p>\n<p><strong>العملة.</strong> جميع المبالغ بالجنيه المصري (EGP) ما لم ينص B6 على خلاف ذلك.</p>\n</section>\n<p>يُشكل ملحق حماية البيانات هذا (المشار إليه بـ <strong>«الملحق»</strong>) جزءًا من اتفاقية خدمات الحضانة بين KiddyApp (بصفته <strong>«المعالج»</strong>) والحضانة (بصفتها <strong>«المتحكم»</strong>). ويطبق على معالجة البيانات الشخصية في سياق الخدمات.</p>\n<h2>1. التعريفات</h2>\n<p>1.2 في هذا الملحق، يكون للألفاظ المكتوبة بحرف كبير ولم تُعرَّف فيه المعاني الممنوحة لها في الاتفاقية. وبالإضافة إلى ذلك:</p>\n<ul>\n<li><strong>«المتحكم»</strong> يعني الحضانة، التي تحدد أغراض ووسائل معالجة بيانات الأطفال وبيانات الأسرة.</li>\n<li><strong>«المعالج»</strong> يعني KiddyApp، التي تعالج البيانات الشخصية نيابةً عن المتحكم.</li>\n<li><strong>«صاحب البيانات»</strong> يعني الطفل أو الوالد أو الوصي أو فرد الأسرة أو الشخص المُصرّح له بالاستلام أو الموظف الذي تُعالج بياناته الشخصية.</li>\n<li><strong>«اختراق البيانات الشخصية»</strong> يعني اختراقًا أمنيًا يؤدي إلى تدمير أو فقدان أو تغيير أو إفصاح غير مُصرّح به عن البيانات الشخصية أو الوصول غير المُصرّح به إليها، سواء كان ذلك عرضيًا أو غير قانوني.</li>\n<li><strong>«المعالجة»</strong> يعني أي عملية تُجرى على البيانات الشخصية، بما في ذلك الجمع والتسجيل والتخزين والاستخدام والإفصاح والنقل والحذف أو الإتلاف.</li>\n<li><strong>«المعالج من الباطن»</strong> يعني طرفًا ثالثًا يستعين به المعالج لمعالجة البيانات الشخصية نيابةً عن المتحكم.</li>\n<li><strong>«النقل المقيّد»</strong> يعني نقل البيانات الشخصية خارج جمهورية مصر العربية إلى دولة أو متلقٍ لا يوفر مستوى حماية مناسبًا بموجب القانون الواجب التطبيق.</li>\n</ul>\n<h2>2. الأدوار والنطاق</h2>\n<p>2.1 تكون الحضانة هي المتحكم في بيانات الأطفال وبيانات الأسرة، ويكون المعالج هو معالج تلك البيانات.</p>\n<p>2.2 لا يعالج المعالج البيانات الشخصية إلا:</p>\n<p>(أ) بناءً على تعليمات المتحكم الموثقة، بما في ذلك التعليمات الواردة في الاتفاقية وهذا الملحق؛</p>\n<p>(ب) بالقدر اللازم لتقديم الخدمات؛</p>\n<p>(ج) حسب ما يقتضيه القانون الواجب التطبيق؛ و</p>\n<p>(د) لغير ذلك من الأغراض.</p>\n<p>2.3 يجب على المعالج إخطار المتحكم إذا رأى أن تعليمًا ما يخالف القانون الواجب التطبيق. ويجوز للمعالج تعليق تنفيذ التعليم حتى يؤكده المتحكم أو يغيره.</p>\n<h2>3. فئات البيانات وأصحابها</h2>\n<p>3.1 يجوز للمعالج معالجة الفئات الآتية من البيانات الشخصية:</p>\n<p>(أ) <strong>بيانات هوية الطفل وتسجيله:</strong> الاسم وتاريخ الميلاد والصورة والجنس والجنسية وحالة التسجيل والفصل ورقم التسجيل.</p>\n<p>(ب) <strong>بيانات صحة الطفل وسلامته:</strong> الحساسية والملاحظات الطبية وتعليمات الأدوية وسجلات الحوادث وجهات الاتصال في حالات الطوارئ.</p>\n<p>(ج) <strong>بيانات نمو الطفل وتعلمه:</strong> الحضور والتقارير اليومية والملاحظات والمعالم التنموية وملاحظات التقييم وعناصر ملف الإنجاز.</p>\n<p>(د) <strong>بيانات الأسرة والوصي:</strong> الاسم وصلة القرابة وبيانات الاتصال وبيانات الهوية حيث تُقدم وتصاريح الاستلام وبيانات جهة الفوترة.</p>\n<p>(هـ) <strong>بيانات الموظفين:</strong> الاسم والدور وبيانات الاتصال وتخصيص الفصل ونشاط تسجيل الدخول.</p>\n<p>(و) <strong>بيانات الاستخدام والأمن:</strong> سجلات تسجيل الدخول ومعلومات الجهاز وعنوان IP وسجلات المراجعة والمراسلات المتعلقة بالدعم.</p>\n<p>3.2 لا يعالج المعالج فئات خاصة من البيانات الشخصية لأغراضه الخاصة. وتُعالج البيانات الصحية فقط لدعم التزامات الحضانة المتعلقة برعاية الأطفال وسلامتهم.</p>\n<p>3.3 يجب على المتحكم عدم تقديم بيانات زائدة أو غير ذات صلة بالخدمات.</p>\n<h2>4. الغرض والأساس القانوني</h2>\n<p>4.1 يعالج المعالج البيانات الشخصية للأغراض الآتية:</p>\n<p>(أ) إنشاء الحساب وإدارته؛</p>\n<p>(ب) تقديم ميزات إدارة رعاية الأطفال، بما في ذلك الحضور والتقارير اليومية والتواصل والسجلات المالية وسجلات التعلم؛</p>\n<p>(ج) تقديم الدعم والصيانة والأمن؛</p>\n<p>(د) منع الاحتيال وإساءة الاستخدام والحوادث الأمنية والكشف عنها والتحقيق فيها؛ و</p>\n<p>(هـ) الامتثال للقانون الواجب التطبيق والطلبات القانونية للجهات المختصة.</p>\n<p>4.2 يتحمل المتحكم مسؤولية تحديد وتوثيق الأساس القانوني لكل نشاط معالجة، بما في ذلك الموافقة حيث تُشترط، ومسؤولية تقديم إخطارات الخصوصية لأصحاب البيانات.</p>\n<p>4.3 يجب على المتحكم الحصول على أي موافقة مطلوبة من أحد الوالدين أو الوصي على معالجة البيانات الشخصية للطفل، بما في ذلك البيانات الصحية والصور.</p>\n<h2>5. التزامات المعالج</h2>\n<p>5.1 يجب على المعالج:</p>\n<p>(أ) معالجة البيانات الشخصية فقط على النحو الموضح في هذا الملحق؛</p>\n<p>(ب) ضمان التزام الأشخاص المصرح لهم بمعالجة البيانات الشخصية بالتزامات السرية؛</p>\n<p>(ج) تنفيذ تدابير فنية وتنظيمية مناسبة لحماية البيانات الشخصية، بما في ذلك ضوابط الوصول والتشفير أثناء النقل والتسجيل والنسخ الاحتياطي والاستجابة للحوادث؛</p>\n<p>(د) مساعدة المتحكم في الرد على طلبات أصحاب البيانات، بالقدر الممكن؛</p>\n<p>(هـ) مساعدة المتحكم في الوفاء بالتزاماته المتعلقة بالأمن والإخطار بالاختراق وتقييمات الأثر والتشاور مع الجهات المختصة؛</p>\n<p>(و) إتاحة المعلومات اللازمة بشكل معقول لإثبات الامتثال لهذا الملحق؛ و</p>\n<p>(ز) السماح بعمليات المراجعة أو التفتيش من قبل المتحكم أو مدققه المستقل، مع مراعاة الإخطار المعقول والسرية والنطاق.</p>\n<p>5.2 يجب على المعالج عدم بيع البيانات الشخصية أو استخدامها للإعلان أو التنميط أو أي غرض غير مرتبط بالخدمات.</p>\n<p>5.3 يجب على المعالج عدم الإفصاح عن البيانات الشخصية لطرف ثالث إلا وفقًا لما يسمح به هذا الملحق أو الاتفاقية أو القانون الواجب التطبيق.</p>\n<h2>6. التزامات المتحكم</h2>\n<p>6.1 يجب على المتحكم:</p>\n<p>(أ) تقديم تعليمات دقيقة وقانونية؛</p>\n<p>(ب) ضمان حقه في مشاركة البيانات الشخصية مع المعالج؛</p>\n<p>(ج) الحصول على جميع الموافقات والإخطارات المطلوبة والاحتفاظ بها؛</p>\n<p>(د) تنفيذ ضوابط وصول داخلية معقولة لمستخدميه؛</p>\n<p>(هـ) الرد على طلبات أصحاب البيانات المتعلقة بالتزامات المتحكم الخاصة؛ و</p>\n<p>(و) إخطار المعالج فورًا بأي تعليم قد يؤثر على قانونية المعالجة.</p>\n<h2>7. المعالجون من الباطن</h2>\n<p>7.1 يفوض المتحكم المعالج بالاستعانة بالمعالجين من الباطن المدرجين في الجدول (أ)، مع مراعاة البند 7.2.</p>\n<p>7.2 يجب على المعالج:</p>\n<p>(أ) إجراء فحص نافٍ للجهالة المناسب لكل معالج من الباطن؛</p>\n<p>(ب) فرض التزامات حماية بيانات على كل معالج من الباطن لا تقل حماية عن هذا الملحق؛</p>\n<p>(ج) يظل مسؤولًا أمام المتحكم عن أفعال معالجيه من الباطن وإغفالاتهم؛ و</p>\n<p>(د) إخطار المتحكم بأي إضافة أو استبدال مقصود لمعالج من الباطن قبل ثلاثين (30) يومًا على الأقل.</p>\n<p>7.3 يجوز للمتحكم الاعتراض على معالج من الباطن الجديد لأسباب معقولة تتعلق بحماية البيانات بإخطار كتابي خلال خمسة عشر (15) يومًا من الإخطار. وإذا لم يتفق الطرفان، جاز للمتحكم تعليق الخدمات المتأثرة أو إنهاءها.</p>\n<h2>8. النقل الدولي</h2>\n<p>8.1 يجب على المعالج عدم إجراء أي نقل مقيّد دون موافقة كتابية مسبقة من المتحكم ودون ضمان وجود الضمانات المناسبة بموجب القانون الواجب التطبيق.</p>\n<p>8.2 إذا استخدم المعالج بنية تحتية أو أفرادًا خارج مصر، وجب عليه إخطار المتحكم وتنفيذ الضمانات التي يقتضيها القانون الواجب التطبيق، بما في ذلك الضمانات التعاقدية والحصول على موافقة الجهة المختصة حيث تُشترط.</p>\n<p>8.3 يجوز للمتحكم رفض أي نقل مقيّد يعتبره بشكل معقول يخلق خطرًا غير مقبول على حماية البيانات.</p>\n<h2>9. الاحتفاظ</h2>\n<p>9.1 يحتفظ المعالج بالبيانات الشخصية فقط للمدة اللازمة لتقديم الخدمات والامتثال للقانون الواجب التطبيق، أو حسب تعليمات المتحكم.</p>\n<p>9.2 ما لم يوجه المتحكم بخلاف ذلك كتابةً ويسمح القانون الواجب التطبيق، يحتفظ المعالج بما يلي:</p>\n<p>(أ) بيانات الحساب النشط خلال مدة الاشتراك؛</p>\n<p>(ب) البيانات القابلة للتصدير لمدة ثلاثين (30) يومًا بعد الإنهاء أو انتهاء المدة؛</p>\n<p>(ج) سجلات المراجعة والسجلات الأمنية للمدة التي يقتضيها القانون الواجب التطبيق؛ و</p>\n<p>(د) سجلات الفوترة للمدة التي يقتضيها قانون الضرائب والتجارة المصري.</p>\n<p>9.3 بعد انتهاء فترة الاحتفاظ، يجب على المعالج حذف البيانات الشخصية أو جعلها مجهولة الهوية ما لم يقتضِ القانون الواجب التطبيق استمرار الاحتفاظ. وإذا كان الحذف مستحيلًا، وجب على المعالج عزل البيانات وحمايتها من أي معالجة لاحقة.</p>\n<h2>10. حقوق أصحاب البيانات</h2>\n<p>10.1 يجب على المعالج، بالقدر الممكن تقنيًا، مساعدة المتحكم في الرد على طلبات الوصول والتصحيح والحذف والتقييد والاعتراض والنقل.</p>\n<p>10.2 إذا تلقى المعالج طلبًا مباشرةً من صاحب بيانات، وجب عليه عدم الرد موضوعيًا نيابةً عن المتحكم ما لم يفوضه المتحكم كتابةً. ويجب على المعالج إحالة الطلب إلى المتحكم دون تأخير غير مبرر.</p>\n<p>10.3 يجوز للمعالج فرض رسم معقول مقابل المساعدة في الطلبات التي لا أساس لها أو المفرطة، مع مراعاة القانون الواجب التطبيق.</p>\n<h2>11. اختراق البيانات الشخصية</h2>\n<p>11.1 يجب على المعالج إخطار المتحكم دون تأخير غير مبرر، وفي جميع الأحوال خلال اثنتين وسبعين (72) ساعة، بعد علمه باختراق بيانات شخصية يؤثر على بيانات المتحكم.</p>\n<p>11.2 يجب أن يتضمن الإخطار، بالقدر المتاح:</p>\n<p>(أ) طبيعة الاختراق وفئات أصحاب البيانات المتأثرين وعددهم التقريبي؛</p>\n<p>(ب) الآثار المحتملة للاختراق؛</p>\n<p>(ج) التدابير المتخذة أو المقترحة لمعالجة الاختراق؛ و</p>\n<p>(د) جهة الاتصال لمزيد من المعلومات.</p>\n<p>11.3 يجب على المعالج التحقيق في الاختراق والتخفيف من آثاره والتعاون مع المتحكم في إخطاراته إلى الجهة المختصة وأصحاب البيانات.</p>\n<p>11.4 يجب على المعالج عدم إخطار جهة مختصة أو صاحب بيانات نيابةً عن المتحكم ما لم يفوضه المتحكم كتابةً أو يقتضِ القانون الواجب التطبيق ذلك.</p>\n<h2>12. التدابير الأمنية</h2>\n<p>12.1 يجب على المعالج تنفيذ وصيانة تدابير فنية وتنظيمية مناسبة، بما في ذلك:</p>\n<p>(أ) التحكم في الوصول القائم على الأدوار ومبادئ الحد الأدنى من الصلاحيات؛</p>\n<p>(ب) ضوابط المصادقة وإدارة الجلسات؛</p>\n<p>(ج) تشفير البيانات أثناء النقل وعند التخزين حيث يكون ذلك مناسبًا؛</p>\n<p>(د) تسجيل ومراقبة الوصول إلى البيانات الشخصية؛</p>\n<p>(هـ) اختبار النسخ الاحتياطي والاستعادة بانتظام؛</p>\n<p>(و) التطوير الآمن وإدارة الثغرات؛ و</p>\n<p>(ز) خطط الاستجابة للحوادث واستمرارية الأعمال.</p>\n<p>12.2 يجب على المتحكم تنفيذ ضوابط مناسبة لمستخدميه وأجهزته وبيانات اعتماده، وعدم مشاركة الحسابات.</p>\n<h2>13. الحذف عند الإنهاء</h2>\n<p>13.1 عند إنهاء الاتفاقية أو انتهاء مدتها، يجب على المعالج، بناءً على توجيه كتابي من المتحكم:</p>\n<p>(أ) إعادة البيانات الشخصية للمتحكم بتنسيق قياسي قابل للقراءة آليًا؛ و</p>\n<p>(ب) حذف البيانات الشخصية للمتحكم من أنظمة الإنتاج لديها، وخلال فترة معقولة من أنظمة النسخ الاحتياطي.</p>\n<p>13.2 يجب على المعالج تقديم شهادة كتابية بالحذف إذا طلب المتحكم ذلك.</p>\n<p>13.3 يجوز للمعالج الاحتفاظ بالبيانات الشخصية حيث يقتضي القانون الواجب التطبيق ذلك، ويجب عليه إخطار المتحكم بالأساس القانوني وفترة الاحتفاظ.</p>\n<p>13.4 إذا لم يقدم المتحكم توجيهًا خلال ثلاثين (30) يومًا بعد الإنهاء، جاز للمعالج حذف البيانات بعد إخطار كتابي.</p>\n<h2>14. المسؤولية وترتيب الأسبقية والقانون الواجب التطبيق</h2>\n<p>14.1 تُطبق أحكام المسؤولية الواردة في الاتفاقية على هذا الملحق.</p>\n<p>14.2 يسود هذا الملحق على الاتفاقية في حال وجود تعارض يتعلق بالبيانات الشخصية.</p>\n<p>14.3 يخضع هذا الملحق لقوانين جمهورية مصر العربية. وتكون النسخة العربية هي المُرجَّحة.</p>\n<p>14.4 يراجع الطرفان هذا الملحق مرة واحدة على الأقل كل اثني عشر (12) شهرًا ويحدثانه ليعكس التغييرات في القانون الواجب التطبيق أو الخدمات.</p>\n<h2>الجدول (أ) — المعالجون من الباطن المصرح لهم</h2>\n<table>\n<thead><tr><th>المعرّف</th><th>المعالج من الباطن</th><th>الخدمة</th><th>موقع المعالجة</th><th>الضمانات</th></tr></thead><tbody>\n<tr><td>S1</td><td><code><span class=\"var\">{{SUBPROCESSOR_1_NAME}}</span></code></td><td>Hosting / database</td><td><code><span class=\"var\">{{SUBPROCESSOR_1_LOCATION}}</span></code></td><td><code><span class=\"var\">{{SUBPROCESSOR_1_SAFEGUARDS}}</span></code></td></tr>\n<tr><td>S2</td><td><code><span class=\"var\">{{SUBPROCESSOR_2_NAME}}</span></code></td><td>Email delivery</td><td><code><span class=\"var\">{{SUBPROCESSOR_2_LOCATION}}</span></code></td><td><code><span class=\"var\">{{SUBPROCESSOR_2_SAFEGUARDS}}</span></code></td></tr>\n<tr><td>S3</td><td><code><span class=\"var\">{{SUBPROCESSOR_3_NAME}}</span></code></td><td>Push notifications</td><td><code><span class=\"var\">{{SUBPROCESSOR_3_LOCATION}}</span></code></td><td><code><span class=\"var\">{{SUBPROCESSOR_3_SAFEGUARDS}}</span></code></td></tr>\n</tbody></table>\n<blockquote><p><strong>ملاحظة للمهندسين.</strong> يجب تأكيد قائمة المعالجين من الباطن في بيئة الإنتاج قبل التوقيع. لا تخمّن أسماء المزودين أو مواقعهم.</p></blockquote>\n<section class=\"annex\" id=\"signatures\"><h1>التوقيع</h1>\n<p>بالتوقيع أدناه، يقر كل طرف بأنه قد قرأ هذه الاتفاقية وجدول طلبها وملحق حماية البيانات الخاص بها ووافق عليها. وتصبح هذه الاتفاقية نافذة في تاريخ النفاذ المبين في جدول الطلب.</p>\n<div class=\"signature\"><div><strong>نيابةً عن KiddyApp</strong><br><br>الاسم: <span class=\"var\">{{PROVIDER_SIGNATORY}}</span><br>المنصب: <span class=\"var\">{{PROVIDER_SIGNATORY_TITLE}}</span><br><br><br>التوقيع: ______________________<br><br>التاريخ: ______________________</div>\n<div><strong>نيابةً عن الحضانة</strong><br><br>الاسم: <span class=\"var\">{{DAYCARE_SIGNATORY}}</span><br>المنصب: <span class=\"var\">{{DAYCARE_SIGNATORY_TITLE}}</span><br><br><br>التوقيع: ______________________<br><br>التاريخ: ______________________</div></div>\n<p class=\"footer-note\">مسودة لمراجعة محامٍ مصري مرخّص. لا تُرسل أو تُوقع قبل تلك المراجعة. النسخة العربية هي المُرجَّحة.</p></section>\n<p class=\"footer-note\">إصدار القالب {{TEMPLATE_VERSION}} — قابل للتعبئة آليًا. استبدل كل متغير بين قوسين مزدوجين؛ ولا تعدل النص القانوني.</p>\n</body>\n</html>\n\n```\n";
